package store

import (
	"context"
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"os"
	"sync/atomic"
	"time"

	_ "github.com/lib/pq"
	"go.mongodb.org/mongo-driver/bson"
	"go.mongodb.org/mongo-driver/mongo"
	"go.mongodb.org/mongo-driver/mongo/options"

	"github.com/go-redis/redis/v8"
	"github.com/google/uuid"
)

type Store struct {
	pg      *sql.DB
	mongo   *mongo.Database
	redis   *redis.Client
	eventSeq int64
}

func New(ctx context.Context) (*Store, error) {
	pgHost := os.Getenv("PGHOST")
	if pgHost == "" {
		pgHost = "/tmp"
	}
	mongoURI := os.Getenv("MONGO_URI")
	if mongoURI == "" {
		mongoURI = "mongodb://127.0.0.1:27017"
	}
	redisAddr := os.Getenv("REDIS_ADDR")
	if redisAddr == "" {
		redisAddr = "127.0.0.1:6379"
	}

	pgConnStr := fmt.Sprintf("host=%s user=agent dbname=lab_samples sslmode=disable", pgHost)
	pgDB, err := sql.Open("postgres", pgConnStr)
	if err != nil {
		return nil, fmt.Errorf("pg open: %w", err)
	}
	if err := pgDB.PingContext(ctx); err != nil {
		return nil, fmt.Errorf("pg ping: %w", err)
	}

	mongoClient, err := mongo.Connect(ctx, options.Client().ApplyURI(mongoURI))
	if err != nil {
		return nil, fmt.Errorf("mongo connect: %w", err)
	}
	mongoDB := mongoClient.Database("lab_samples")

	rdb := redis.NewClient(&redis.Options{Addr: redisAddr})
	if err := rdb.Ping(ctx).Err(); err != nil {
		return nil, fmt.Errorf("redis ping: %w", err)
	}

	s := &Store{pg: pgDB, mongo: mongoDB, redis: rdb}
	s.eventSeq = s.loadEventSeq(ctx)
	return s, nil
}

func (s *Store) PG() *sql.DB      { return s.pg }
func (s *Store) Mongo() *mongo.Database { return s.mongo }
func (s *Store) Redis() *redis.Client   { return s.redis }

func (s *Store) loadEventSeq(ctx context.Context) int64 {
	val, _ := s.redis.Get(ctx, "event:seq").Int64()
	return val
}

func (s *Store) NextEventID(ctx context.Context) int64 {
	return atomic.AddInt64(&s.eventSeq, 1)
}

func (s *Store) PersistEventSeq(ctx context.Context) {
	s.redis.Set(ctx, "event:seq", s.eventSeq, 0)
}

func (s *Store) EnsurePG(ctx context.Context) error {
	return s.pg.PingContext(ctx)
}

func (s *Store) EnsureMongo(ctx context.Context) error {
	return s.mongo.Client().Ping(ctx, nil)
}

func (s *Store) EnsureRedis(ctx context.Context) error {
	return s.redis.Ping(ctx).Err()
}

func (s *Store) RunMigrations(ctx context.Context) error {
	ddl := `
	CREATE EXTENSION IF NOT EXISTS "pgcrypto";

	CREATE TABLE IF NOT EXISTS users (
		user_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
		username TEXT UNIQUE NOT NULL,
		password_hash TEXT NOT NULL,
		full_name TEXT NOT NULL DEFAULT '',
		roles JSONB NOT NULL DEFAULT '[]',
		qualifications JSONB NOT NULL DEFAULT '[]',
		certifications JSONB NOT NULL DEFAULT '[]',
		active BOOLEAN NOT NULL DEFAULT true,
		assigned_location_id UUID,
		active_role TEXT DEFAULT '',
		available BOOLEAN NOT NULL DEFAULT false,
		capacity_units INT NOT NULL DEFAULT 0,
		current_lat DOUBLE PRECISION,
		current_lng DOUBLE PRECISION,
		location_recorded_at TIMESTAMPTZ,
		decline_count INT NOT NULL DEFAULT 0,
		last_decline_at TIMESTAMPTZ,
		created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
		updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
	);

	CREATE TABLE IF NOT EXISTS locations (
		location_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
		name TEXT NOT NULL,
		latitude DOUBLE PRECISION NOT NULL,
		longitude DOUBLE PRECISION NOT NULL,
		coverage_km DOUBLE PRECISION NOT NULL DEFAULT 5,
		handling_minutes INT NOT NULL DEFAULT 0,
		active BOOLEAN NOT NULL DEFAULT true,
		functions JSONB NOT NULL DEFAULT '{}',
		created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
		updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
	);

	CREATE TABLE IF NOT EXISTS connections (
		connection_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
		from_location_id UUID NOT NULL REFERENCES locations(location_id),
		to_location_id UUID NOT NULL REFERENCES locations(location_id),
		travel_minutes INT NOT NULL,
		cost_units DOUBLE PRECISION NOT NULL DEFAULT 0,
		cooled BOOLEAN NOT NULL DEFAULT false,
		active BOOLEAN NOT NULL DEFAULT true,
		created_at TIMESTAMPTZ NOT NULL DEFAULT now()
	);

	CREATE TABLE IF NOT EXISTS sample_types (
		sample_type_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
		name TEXT NOT NULL,
		qualified_collector_required BOOLEAN NOT NULL DEFAULT false,
		required_qualification TEXT NOT NULL DEFAULT '',
		container_type TEXT NOT NULL DEFAULT '',
		temperature_min_c DOUBLE PRECISION NOT NULL DEFAULT 0,
		temperature_max_c DOUBLE PRECISION NOT NULL DEFAULT 30,
		incompatible_sample_types JSONB NOT NULL DEFAULT '[]',
		requires_cooled_route BOOLEAN NOT NULL DEFAULT false,
		batching_allowed BOOLEAN NOT NULL DEFAULT true,
		created_at TIMESTAMPTZ NOT NULL DEFAULT now()
	);

	CREATE TABLE IF NOT EXISTS samples (
		sample_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
		request_id UUID NOT NULL,
		requester_id UUID NOT NULL REFERENCES users(user_id),
		origin_lat DOUBLE PRECISION NOT NULL,
		origin_lng DOUBLE PRECISION NOT NULL,
		origin_type TEXT NOT NULL DEFAULT 'home',
		origin_node_id UUID,
		requested_at TIMESTAMPTZ NOT NULL DEFAULT now(),
		delivery_deadline TIMESTAMPTZ NOT NULL,
		earliest_collection_at TIMESTAMPTZ,
		latest_collection_at TIMESTAMPTZ,
		sample_type_id UUID NOT NULL REFERENCES sample_types(sample_type_id),
		container_type TEXT NOT NULL DEFAULT '',
		temperature_min_c DOUBLE PRECISION NOT NULL DEFAULT 0,
		temperature_max_c DOUBLE PRECISION NOT NULL DEFAULT 30,
		incompatible_sample_types JSONB NOT NULL DEFAULT '[]',
		status TEXT NOT NULL DEFAULT 'requested',
		sealed BOOLEAN NOT NULL DEFAULT false,
		current_holder_id UUID,
		active_journey_id UUID,
		target_laboratory_id UUID,
		received_laboratory_id UUID,
		serviceability TEXT NOT NULL DEFAULT 'unserviceable',
		exception JSONB,
		pending_handoff_id UUID,
		latest_lat DOUBLE PRECISION,
		latest_lng DOUBLE PRECISION,
		location_recorded_at TIMESTAMPTZ,
		created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
		updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
	);

	CREATE TABLE IF NOT EXISTS journeys (
		journey_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
		parent_journey_id UUID,
		plan_version INT NOT NULL DEFAULT 1,
		route_mode TEXT NOT NULL DEFAULT 'direct',
		status TEXT NOT NULL DEFAULT 'planned',
		estimated_delivery_at TIMESTAMPTZ,
		total_cost_units DOUBLE PRECISION NOT NULL DEFAULT 0,
		capacity_used INT NOT NULL DEFAULT 0,
		capacity_available INT NOT NULL DEFAULT 0,
		sample_ids JSONB NOT NULL DEFAULT '[]',
		ordered_stops JSONB NOT NULL DEFAULT '[]',
		legs JSONB NOT NULL DEFAULT '[]',
		assigned_worker_ids JSONB NOT NULL DEFAULT '[]',
		collection_assignment_id UUID,
		collection_assignment_ids JSONB NOT NULL DEFAULT '[]',
		node_assignment_ids JSONB NOT NULL DEFAULT '[]',
		laboratory_assignment_ids JSONB NOT NULL DEFAULT '[]',
		first_transport_assignment_id UUID,
		middle_transport_assignment_id UUID,
		final_transport_assignment_id UUID,
		valid BOOLEAN NOT NULL DEFAULT true,
		replan_status TEXT DEFAULT '',
		created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
		updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
	);

	CREATE TABLE IF NOT EXISTS assignments (
		assignment_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
		kind TEXT NOT NULL,
		sample_id UUID NOT NULL REFERENCES samples(sample_id),
		journey_id UUID NOT NULL,
		from_location_id UUID,
		to_location_id UUID,
		sequence INT NOT NULL DEFAULT 0,
		worker_id UUID,
		status TEXT NOT NULL DEFAULT 'offered',
		offer_expires_at TIMESTAMPTZ,
		node_id UUID,
		incoming_from_location_id UUID,
		outgoing_to_location_id UUID,
		laboratory_id UUID,
		expected_sample_type_id UUID,
		progress_status TEXT DEFAULT '',
		cooled BOOLEAN NOT NULL DEFAULT false,
		created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
		updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
	);

	CREATE TABLE IF NOT EXISTS handoffs (
		handoff_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
		sample_id UUID NOT NULL REFERENCES samples(sample_id),
		from_worker_id UUID NOT NULL,
		to_worker_id UUID NOT NULL,
		from_location_id UUID,
		to_location_id UUID,
		status TEXT NOT NULL DEFAULT 'initiated',
		sender_confirmed BOOLEAN NOT NULL DEFAULT false,
		receiver_confirmed BOOLEAN NOT NULL DEFAULT false,
		initiated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
		sender_confirmed_at TIMESTAMPTZ,
		receiver_confirmed_at TIMESTAMPTZ,
		current_holder_id UUID NOT NULL
	);

	CREATE TABLE IF NOT EXISTS capacity_reservations (
		reservation_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
		resource_type TEXT NOT NULL,
		resource_id UUID NOT NULL,
		journey_id UUID NOT NULL,
		cooled BOOLEAN NOT NULL DEFAULT false,
		units INT NOT NULL DEFAULT 1,
		created_at TIMESTAMPTZ NOT NULL DEFAULT now()
	);

	CREATE TABLE IF NOT EXISTS handling_checkpoints (
		checkpoint_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
		sample_id UUID NOT NULL REFERENCES samples(sample_id),
		worker_id UUID NOT NULL,
		container_type TEXT NOT NULL,
		observed_temperature_c DOUBLE PRECISION NOT NULL,
		recorded_at TIMESTAMPTZ NOT NULL DEFAULT now()
	);

	CREATE TABLE IF NOT EXISTS laboratory_acceptances (
		acceptance_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
		laboratory_id UUID NOT NULL REFERENCES locations(location_id),
		sample_type_id UUID NOT NULL REFERENCES sample_types(sample_type_id),
		accepts BOOLEAN NOT NULL DEFAULT false,
		UNIQUE(laboratory_id, sample_type_id)
	);

	CREATE TABLE IF NOT EXISTS location_capacity (
		location_id UUID PRIMARY KEY REFERENCES locations(location_id),
		capacity_units INT NOT NULL DEFAULT 0,
		reserved_units INT NOT NULL DEFAULT 0,
		cooled_capacity_units INT NOT NULL DEFAULT 0,
		cooled_reserved_units INT NOT NULL DEFAULT 0
	);

	CREATE TABLE IF NOT EXISTS connection_capacity (
		connection_id UUID PRIMARY KEY REFERENCES connections(connection_id),
		capacity_units INT NOT NULL DEFAULT 0,
		reserved_units INT NOT NULL DEFAULT 0,
		cooled_capacity_units INT NOT NULL DEFAULT 0,
		cooled_reserved_units INT NOT NULL DEFAULT 0
	);

	CREATE TABLE IF NOT EXISTS serviceability_versions (
		version INT PRIMARY KEY,
		computed_at TIMESTAMPTZ NOT NULL DEFAULT now(),
		data JSONB NOT NULL
	);

	CREATE TABLE IF NOT EXISTS disruptions (
		disruption_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
		resource_type TEXT NOT NULL,
		resource_id TEXT NOT NULL,
		reason TEXT NOT NULL DEFAULT '',
		occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(),
		affected_sample_ids JSONB NOT NULL DEFAULT '[]',
		replacement_plan_ids JSONB NOT NULL DEFAULT '[]',
		replan_status TEXT NOT NULL DEFAULT 'replanned',
		created_at TIMESTAMPTZ NOT NULL DEFAULT now()
	);

	-- Indexes
	CREATE INDEX IF NOT EXISTS idx_samples_requester ON samples(requester_id);
	CREATE INDEX IF NOT EXISTS idx_samples_holder ON samples(current_holder_id);
	CREATE INDEX IF NOT EXISTS idx_samples_journey ON samples(active_journey_id);
	CREATE INDEX IF NOT EXISTS idx_samples_status ON samples(status);
	CREATE INDEX IF NOT EXISTS idx_assignments_worker ON assignments(worker_id);
	CREATE INDEX IF NOT EXISTS idx_assignments_journey ON assignments(journey_id);
	CREATE INDEX IF NOT EXISTS idx_assignments_status ON assignments(status);
	CREATE INDEX IF NOT EXISTS idx_journeys_status ON journeys(status);
	CREATE INDEX IF NOT EXISTS idx_handoffs_sample ON handoffs(sample_id);
	CREATE INDEX IF NOT EXISTS idx_capacity_resource ON capacity_reservations(resource_type, resource_id);
	`

	_, err := s.pg.ExecContext(ctx, ddl)
	if err != nil {
		return fmt.Errorf("migrations: %w", err)
	}

	// Ensure MongoDB collections and indexes
	auditColl := s.mongo.Collection("audit_logs")
	auditColl.Indexes().CreateMany(ctx, []mongo.IndexModel{
		{Keys: bson.D{{Key: "entity_id", Value: 1}}},
		{Keys: bson.D{{Key: "actor_id", Value: 1}}},
		{Keys: bson.D{{Key: "occurred_at", Value: -1}}},
		{Keys: bson.D{{Key: "entity_type", Value: 1}}},
		{Keys: bson.D{{Key: "action", Value: 1}}},
	})

	eventsColl := s.mongo.Collection("events")
	eventsColl.Indexes().CreateMany(ctx, []mongo.IndexModel{
		{Keys: bson.D{{Key: "id", Value: 1}}},
	})

	timelineColl := s.mongo.Collection("timeline_events")
	timelineColl.Indexes().CreateMany(ctx, []mongo.IndexModel{
		{Keys: bson.D{{Key: "sample_id", Value: 1}}},
		{Keys: bson.D{{Key: "event_id", Value: 1}}},
