package middleware

import (
	"context"
	"encoding/base64"
	"encoding/json"
	"net/http"
	"strings"

	"github.com/golang-jwt/jwt/v5"
	"github.com/google/uuid"
)

type contextKey string

const (
	UserIDKey    contextKey = "user_id"
	RoleKey      contextKey = "active_role"
	RolesKey     contextKey = "user_roles"
	TokenKey     contextKey = "session_token"
)

var jwtSecret []byte

func SetJWTSecret(secret []byte) {
	jwtSecret = secret
}

func GenerateToken(userID, activeRole string, roles []string) (string, error) {
	claims := jwt.MapClaims{
		"user_id":     userID,
		"active_role": activeRole,
		"roles":       roles,
		"jti":         uuid.New().String(),
	}
	token := jwt.NewWithClaims(jwt.SigningMethodHS256, claims)
	return token.SignedString(jwtSecret)
}

func AuthMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		auth := r.Header.Get("Authorization")
		if auth == "" {
			auth = r.URL.Query().Get("token")
		}
		if auth == "" || !strings.HasPrefix(auth, "Bearer ") {
			http.Error(w, `{"error":"unauthorized","code":"unauthorized"}`, http.StatusUnauthorized)
			return
		}

		tokenStr := strings.TrimPrefix(auth, "Bearer ")
		token, err := jwt.Parse(tokenStr, func(t *jwt.Token) (interface{}, error) {
			return jwtSecret, nil
		})
		if err != nil || !token.Valid {
			http.Error(w, `{"error":"unauthorized","code":"unauthorized"}`, http.StatusUnauthorized)
			return
		}

		claims, ok := token.Claims.(jwt.MapClaims)
		if !ok {
			http.Error(w, `{"error":"unauthorized","code":"unauthorized"}`, http.StatusUnauthorized)
			return
		}

		ctx := context.WithValue(r.Context(), UserIDKey, claims["user_id"].(string))
		ctx = context.WithValue(ctx, RoleKey, claims["active_role"].(string))
		ctx = context.WithValue(ctx, TokenKey, tokenStr)

		roles := []string{}
		if r, ok := claims["roles"].([]interface{}); ok {
			for _, role := range r {
				roles = append(roles, role.(string))
			}
		}
		ctx = context.WithValue(ctx, RolesKey, roles)

		next.ServeHTTP(w, r.WithContext(ctx))
	})
}

func GetUserID(r *http.Request) string {
	if v, ok := r.Context().Value(UserIDKey).(string); ok {
		return v
	}
	return ""
}

func GetActiveRole(r *http.Request) string {
	if v, ok := r.Context().Value(RoleKey).(string); ok {
		return v
	}
	return ""
}

func GetRoles(r *http.Request) []string {
	if v, ok := r.Context().Value(RolesKey).(string); ok {
		return strings.Split(v, ",")
	}
	return nil
}

func HasRole(r *http.Request, role string) bool {
	active := GetActiveRole(r)
	return active == role || active == "administrator"
}

func WSSubprotocolAuth(subprotocol string) (string, string, []string, error) {
	parts := strings.SplitN(subprotocol, ".", 2)
	if len(parts) != 2 || parts[0] != "bearer" {
		return "", "", nil, jwt.ErrSignatureInvalid
	}
	tokenStr, err := base64.RawURLEncoding.DecodeString(parts[1])
	if err != nil {
		return "", "", nil, err
	}
	token, err := jwt.Parse(string(tokenStr), func(t *jwt.Token) (interface{}, error) {
		return jwtSecret, nil
	})
	if err != nil || !token.Valid {
		return "", "", nil, err
	}
	claims, ok := token.Claims.(jwt.MapClaims)
	if !ok {
		return "", "", nil, err
	}
	uid := claims["user_id"].(string)
	ar := claims["active_role"].(string)
	roles := []string{}
	if r, ok := claims["roles"].([]interface{}); ok {
		for _, role := range r {
			roles = append(roles, role.(string))
		}
	}
	return uid, ar, roles, nil
}

func WriteJSON(w http.ResponseWriter, status int, v interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.Header().Set("Cache-Control", "no-store")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(v)
}

func WriteError(w http.ResponseWriter, status int, code, msg string) {
	WriteJSON(w, status, map[string]string{"error": msg, "code": code})
}

