package store

import (
	"context"
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"os"
	"sync/atomic"
	"time"

	_ "github.com/lib/pq"
	"go.mongodb.org/mongo-driver/bson"
	"go.mongodb.org/mongo-driver/mongo"
	"go.mongodb.org/mongo-driver/mongo/options"

	"github.com/go-redis/redis/v8"
	"github.com/google/uuid"
)

type Store struct {
	pg      *sql.DB
	mongo   *mongo.Database
	redis   *redis.Client
	eventSeq int64
}

func New(ctx context.Context) (*Store, error) {
	pgHost := os.Getenv("PGHOST")
	if pgHost == "" {
		pgHost = "/tmp"
	}
	mongoURI := os.Getenv("MONGO_URI")
	if mongoURI == "" {
		mongoURI = "mongodb://127.0.0.1:27017"
	}
	redisAddr := os.Getenv("REDIS_ADDR")
	if redisAddr == "" {
		redisAddr = "127.0.0.1:6379"
	}

	pgConnStr := fmt.Sprintf("host=%s user=agent dbname=lab_samples sslmode=disable", pgHost)
	pgDB, err := sql.Open("postgres", pgConnStr)
	if err != nil {
		return nil, fmt.Errorf("pg open: %w", err)
	}
	if err := pgDB.PingContext(ctx); err != nil {
		return nil, fmt.Errorf("pg ping: %w", err)
	}

	mongoClient, err := mongo.Connect(ctx, options.Client().ApplyURI(mongoURI))
	if err != nil {
		return nil, fmt.Errorf("mongo connect: %w", err)
	}
	mongoDB := mongoClient.Database("lab_samples")

	rdb := redis.NewClient(&redis.Options{Addr: redisAddr})
	if err := rdb.Ping(ctx).Err(); err != nil {
		return nil, fmt.Errorf("redis ping: %w", err)
	}

	s := &Store{pg: pgDB, mongo: mongoDB, redis: rdb}
	s.eventSeq = s.loadEventSeq(ctx)
	return s, nil
}

func (s *Store) PG() *sql.DB      { return s.pg }
func (s *Store) Mongo() *mongo.Database { return s.mongo }
func (s *Store) Redis() *redis.Client   { return s.redis }

func (s *Store) loadEventSeq(ctx context.Context) int64 {
	val, _ := s.redis.Get(ctx, "event:seq").Int64()
	return val
}

func (s *Store) NextEventID(ctx context.Context) int64 {
	return atomic.AddInt64(&s.eventSeq, 1)
}

func (s *Store) PersistEventSeq(ctx context.Context) {
	s.redis.Set(ctx, "event:seq", s.eventSeq, 0)
}

func (s *Store) EnsurePG(ctx context.Context) error {
	return s.pg.PingContext(ctx)
}

func (s *Store) EnsureMongo(ctx context.Context) error {
	return s.mongo.Client().Ping(ctx, nil)
}

func (s *Store) EnsureRedis(ctx context.Context) error {
	return s.redis.Ping(ctx).Err()
}

func (s *Store) RunMigrations(ctx context.Context) error {
	ddl := `
	CREATE EXTENSION IF NOT EXISTS "pgcrypto";

	CREATE TABLE IF NOT EXISTS users (
		user_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
		username TEXT UNIQUE NOT NULL,
		password_hash TEXT NOT NULL,
		full_name TEXT NOT NULL DEFAULT '',
		roles JSONB NOT NULL DEFAULT '[]',
		qualifications JSONB NOT NULL DEFAULT '[]',
		certifications JSONB NOT NULL DEFAULT '[]',
		active BOOLEAN NOT NULL DEFAULT true,
		assigned_location_id UUID,
		active_role TEXT DEFAULT '',
		available BOOLEAN NOT NULL DEFAULT false,
		capacity_units INT NOT NULL DEFAULT 0,
		current_lat DOUBLE PRECISION,
		current_lng DOUBLE PRECISION,
		location_recorded_at TIMESTAMPTZ,
		decline_count INT NOT NULL DEFAULT 0,
		last_decline_at TIMESTAMPTZ,
		created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
		updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
	);

	CREATE TABLE IF NOT EXISTS locations (
		location_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
		name TEXT NOT NULL,
		latitude DOUBLE PRECISION NOT NULL,
		longitude DOUBLE PRECISION NOT NULL,
		coverage_km DOUBLE PRECISION NOT NULL DEFAULT 5,
		handling_minutes INT NOT NULL DEFAULT 0,
		active BOOLEAN NOT NULL DEFAULT true,
		functions JSONB NOT NULL DEFAULT '{}',
		created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
		updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
	);

	CREATE TABLE IF NOT EXISTS connections (
		connection_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
		from_location_id UUID NOT NULL REFERENCES locations(location_id),
		to_location_id UUID NOT NULL REFERENCES locations(location_id),
		travel_minutes INT NOT NULL,
		cost_units DOUBLE PRECISION NOT NULL DEFAULT 0,
		cooled BOOLEAN NOT NULL DEFAULT false,
		active BOOLEAN NOT NULL DEFAULT true,
		created_at TIMESTAMPTZ NOT NULL DEFAULT now()
	);

	CREATE TABLE IF NOT EXISTS sample_types (
		sample_type_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
		name TEXT NOT NULL,
		qualified_collector_required BOOLEAN NOT NULL DEFAULT false,
		required_qualification TEXT NOT NULL DEFAULT '',
		container_type TEXT NOT NULL DEFAULT '',
		temperature_min_c DOUBLE PRECISION NOT NULL DEFAULT 0,
		temperature_max_c DOUBLE PRECISION NOT NULL DEFAULT 30,
		incompatible_sample_types JSONB NOT NULL DEFAULT '[]',
		requires_cooled_route BOOLEAN NOT NULL DEFAULT false,
		batching_allowed BOOLEAN NOT NULL DEFAULT true,
		created_at TIMESTAMPTZ NOT NULL DEFAULT now()
	);

	CREATE TABLE IF NOT EXISTS samples (
