type Store struct {
	pg      *sql.DB
	mongo   *mongo.Database
	redis   *redis.Client
	eventSeq int64
}

func New(ctx context.Context) (*Store, error) {
	pgHost := os.Getenv("PGHOST")
	if pgHost == "" {
		pgHost = "/tmp"
	}
	mongoURI := os.Getenv("MONGO_URI")
	if mongoURI == "" {
		mongoURI = "mongodb://127.0.0.1:27017"
	}
	redisAddr := os.Getenv("REDIS_ADDR")
	if redisAddr == "" {
		redisAddr = "127.0.0.1:6379"
	}

	pgConnStr := fmt.Sprintf("host=%s user=agent dbname=lab_samples sslmode=disable", pgHost)
	pgDB, err := sql.Open("postgres", pgConnStr)
	if err != nil {
		return nil, fmt.Errorf("pg open: %w", err)
	}
	if err := pgDB.PingContext(ctx); err != nil {
		return nil, fmt.Errorf("pg ping: %w", err)
	}

	mongoClient, err := mongo.Connect(ctx, options.Client().ApplyURI(mongoURI))
	if err != nil {
		return nil, fmt.Errorf("mongo connect: %w", err)
	}
	mongoDB := mongoClient.Database("lab_samples")

	rdb := redis.NewClient(&redis.Options{Addr: redisAddr})
	if err := rdb.Ping(ctx).Err(); err != nil {
		return nil, fmt.Errorf("redis ping: %w", err)
	}

	s := &Store{pg: pgDB, mongo: mongoDB, redis: rdb}
	s.eventSeq = s.loadEventSeq(ctx)
	return s, nil
}

func (s *Store) PG() *sql.DB      { return s.pg }
func (s *Store) Mongo() *mongo.Database { return s.mongo }
func (s *Store) Redis() *redis.Client   { return s.redis }

func (s *Store) loadEventSeq(ctx context.Context) int64 {
	val, _ := s.redis.Get(ctx, "event:seq").Int64()
	return val
}

func (s *Store) NextEventID(ctx context.Context) int64 {
	return atomic.AddInt64(&s.eventSeq, 1)
}

func (s *Store) PersistEventSeq(ctx context.Context) {
	s.redis.Set(ctx, "event:seq", s.eventSeq, 0)
}

func (s *Store) EnsurePG(ctx context.Context) error {
	return s.pg.PingContext(ctx)
}

func (s *Store) EnsureMongo(ctx context.Context) error {
	return s.mongo.Client().Ping(ctx, nil)
}

func (s *Store) EnsureRedis(ctx context.Context) error {
	return s.redis.Ping(ctx).Err()
