func (h *Handler) ReadUIBootstrap(w http.ResponseWriter, r *http.Request) {
	uid := middleware.GetUserID(r)
	role := middleware.GetActiveRole(r)
	ctx := r.Context()

	var username, fullName string
	var rolesJSON []byte
	h.store.PG().QueryRowContext(ctx, "SELECT username, full_name, roles FROM users WHERE user_id=$1", uid).Scan(&username, &fullName, &rolesJSON)
	var roles []string
	json.Unmarshal(rolesJSON, &roles)

	user := map[string]interface{}{
		"userId":     uid,
		"username":   username,
		"fullName":   fullName,
		"roles":      roles,
		"activeRole": role,
	}

	response := map[string]interface{}{
		"data": map[string]interface{}{
			"user":       user,
			"serverTime": time.Now(),
		},
	}

	if role == "requester" {
		var reqSamples []map[string]interface{}
		rows, _ := h.store.PG().QueryContext(ctx, "SELECT sample_id, status, serviceability FROM samples WHERE requester_id=$1 ORDER BY created_at DESC LIMIT 100", uid)
		if rows != nil {
			defer rows.Close()
			for rows.Next() {
				var sid, status, svc string
				rows.Scan(&sid, &status, &svc)
				reqSamples = append(reqSamples, map[string]interface{}{
					"sampleId": sid, "status": status, "serviceability": svc,
				})
			}
		}
		response["data"].(map[string]interface{})["requesterSamples"] = reqSamples
	}

	if role == "dispatcher" || role == "administrator" {
		ops := h.buildOperationsState(ctx)
		response["data"].(map[string]interface{})["operations"] = ops
	}

	middleware.WriteJSON(w, 200, response)
}

// ============================== WEBSOCKET ==============================

func (h *Handler) StreamRealtimeEvents(w http.ResponseWriter, r *http.Request) {
	proto := r.Header.Get("Sec-WebSocket-Protocol")
	uid, role, roles, err := middleware.WSSubprotocolAuth(proto)
	if err != nil {
		middleware.WriteError(w, 401, "unauthorized", "ws auth failed")
		return
	}

	sinceStr := r.URL.Query().Get("since")
	var since int64
	if sinceStr != "" {
		since, _ = strconv.ParseInt(sinceStr, 10, 64)
	}

	conn, err := upgrader.Upgrade(w, r, http.Header{"Sec-WebSocket-Protocol": {proto}})
	if err != nil {
		return
	}

	wsc := &wsConn{conn: conn, userID: uid, role: role, roles: roles, since: since}

	// Register connection
	clients, _ := h.wsClients.LoadOrStore(role, &sync.Map{})
	connID := uuid.New().String()
	clients.(*sync.Map).Store(connID, wsc)

	defer func() {
		if cmap, ok := h.wsClients.Load(role); ok {
			cmap.(*sync.Map).Delete(connID)
		}
		conn.Close()
	}()

	// Send replay events if since > 0
	if since > 0 {
		ctx := r.Context()
		cursor, _ := h.store.Mongo().Collection("events").Find(ctx,
			bson.M{"id": bson.M{"$gt": since}},
			options.Find().SetSort(bson.D{{Key: "id", Value: 1}}))
		if cursor != nil {
			var events []models.RealtimeEvent
			cursor.All(ctx, &events)
			for _, evt := range events {
				conn.WriteJSON(evt)
			}
		}
	}

	// Keep alive
	for {
		_, _, err := conn.ReadMessage()
		if err != nil {
			break
		}
	}
}

func (h *Handler) emitEvent(ctx context.Context, eventType, entityType, entityID string, payload map[string]interface{}) {
	seq := h.store.NextEventID(ctx)
	event := models.RealtimeEvent{
		ID:         seq,
		Type:       eventType,
		EntityType: entityType,
		EntityID:   entityID,
		Payload:    payload,
		CreatedAt:  time.Now(),
	}

	// Save to MongoDB
	h.store.Mongo().Collection("events").InsertOne(context.Background(), event)

	// Store latest seq in redis
	h.store.Redis().Set(context.Background(), "event:latest", seq, 0)

	// Broadcast to relevant WebSocket clients
	eventJSON, _ := json.Marshal(event)

	h.wsClients.Range(func(roleKey, clients interface{}) bool {
		cmap := clients.(*sync.Map)
		cmap.Range(func(key, value interface{}) bool {
			wsc := value.(*wsConn)
			if wsc.since < seq {
				wsc.conn.WriteMessage(websocket.TextMessage, eventJSON)
			}
			return true
		})
		return true
	})

	h.store.PersistEventSeq(context.Background())
}

