#!/bin/bash
set -e

# Ensure datastores are running
pg_isready -h /tmp -q 2>/dev/null || {
  /usr/lib/postgresql/16/bin/pg_ctl -D /tmp/pgdata -o "-k /tmp" -l /tmp/pg.log start -w
}

mongosh --eval "db.version()" --quiet 2>/dev/null || {
  mongod --dbpath /tmp/mongodata --fork --logpath /tmp/mongo.log
}

redis-cli ping >/dev/null 2>&1 || {
  redis-server --daemonize yes --logfile /tmp/redis.log
}

export PGHOST=/tmp
export MONGO_URI="mongodb://127.0.0.1:27017"
export REDIS_ADDR="127.0.0.1:6379"

# Run the backend (blocking)
cd /workspace/backend
exec ./server

