#!/bin/bash
set -e

# Ensure PostgreSQL is running for reset
pg_isready -h /tmp -q 2>/dev/null || {
  /usr/lib/postgresql/16/bin/pg_ctl -D /tmp/pgdata -o "-k /tmp" -l /tmp/pg.log start -w
}

export PGHOST=/tmp

# Create database if needed
createdb -h /tmp lab_samples 2>/dev/null || true

# Drop all tables
psql -h /tmp lab_samples -c "
DO \$\$ DECLARE r RECORD;
BEGIN
  FOR r IN (SELECT tablename FROM pg_tables WHERE schemaname='public') LOOP
    EXECUTE 'DROP TABLE IF EXISTS ' || quote_ident(r.tablename) || ' CASCADE';
  END LOOP;
END \$\$;
" 2>&1

# Ensure MongoDB and Redis are reachable
mongosh --eval "db.dropDatabase()" --quiet mongodb://127.0.0.1:27017/lab_samples 2>/dev/null || true
redis-cli FLUSHALL 2>/dev/null || true

echo "Reset complete"

