paths = c['paths']

# Check request body schemas for each endpoint
for path, methods in sorted(paths.items()):
    for method, details in sorted(methods.items()):
        opid = details.get('operationId', '???')
        rb = details.get('requestBody', {})
        content = rb.get('content', {}).get('application/json', {})
        schema = content.get('schema', {})
        ref = schema.get('\$ref', '')
        props = schema.get('properties', {})
        req = schema.get('required', [])

        if ref:
            print(f'{opid}: body -> {ref}')
        elif props:
            print(f'{opid}: body -> {list(props.keys())} required={req}')
        else:
            # Check parameters
            params = details.get('parameters', [])
            if params:
                for p in params:
                    print(f'{opid}: param -> {p[\"name\"]} ({p[\"in\"]})')
            else:
                print(f'{opid}: (no body, no params)')
" 2>&1", "timeout": 10}

