export type Role = 'administrator' | 'dispatcher' | 'requester' | 'collection_professional' | 'delivery_partner' | 'node_handler' | 'laboratory_team';

export interface Coordinate {
  latitude: number;
  longitude: number;
}

export interface AuthUser {
  userId: string;
  username: string;
  fullName: string;
  roles: Role[];
  activeRole: Role;
  token: string;
  assignedLocationId?: string;
  qualifications: string[];
  certifications: Certification[];
  available: boolean;
  capacityUnits: number;
}

export interface Certification {
  code: string;
  active: boolean;
  expiresAt?: string;
}

export interface Location {
  locationId: string;
  name: string;
  coordinate: Coordinate;
  coverageKm: number;
  handlingMinutes: number;
  active: boolean;
  functions: LocationFunctions;
}

export interface LocationFunctions {
  collection_point?: boolean;
  transfer_point?: boolean;
  hub?: boolean;
  laboratory?: boolean;
}

export interface Connection {
  connectionId: string;
  fromLocationId: string;
  toLocationId: string;
  travelMinutes: number;
  costUnits: number;
  cooled: boolean;
  active: boolean;
}

export interface SampleType {
  sampleTypeId: string;
  name: string;
  qualifiedCollectorRequired: boolean;
  requiredQualification: string;
  containerType: string;
  temperatureMinC: number;
  temperatureMaxC: number;
  incompatibleSampleTypes: string[];
  requiresCooledRoute: boolean;
  batchingAllowed: boolean;
}

export interface SampleState {
  sampleId: string;
  requestId: string;
  requesterId: string;
  origin: Coordinate;
  originType: string;
  requestedAt: string;
  deliveryDeadline: string;
  earliestCollectionAt?: string;
  latestCollectionAt?: string;
  sampleTypeId: string;
  containerType: string;
  temperatureMinC: number;
  temperatureMaxC: number;
  incompatibleSampleTypes: string[];
  serviceability: string;
  activeAssignmentIds: string[];
  state: Record<string, unknown>;
  timeline: TimelineEntry[];
  activeJourneyId?: string;
  targetLaboratoryId?: string;
  latestLocation?: Coordinate;
  locationRecordedAt?: string;
  locationStale: boolean;
}

export interface TimelineEntry {
  eventId: number;
  action: string;
  actorId: string;
  role: string;
  entityType: string;
  entityId: string;
  success: boolean;
  occurredAt: string;
  details: Record<string, unknown>;
}

export interface SampleLifecycle {
  sampleId: string;
  status: string;
