  requiresCooledRoute?: boolean;
  batchingAllowed?: boolean;
}) {
  return request<{ data: { sampleTypeId: string } }>('POST', '/create-sample-type', params);
}

export function updateSampleType(params: {
  sampleTypeId: string;
  qualifiedCollectorRequired?: boolean;
  requiredQualification?: string;
  containerType: string;
  temperatureMinC: number;
  temperatureMaxC: number;
  incompatibleSampleTypes?: string[];
  requiresCooledRoute?: boolean;
  batchingAllowed?: boolean;
}) {
  return request<{ data: { sampleTypeId: string } }>('POST', '/update-sample-type', params);
}

// Capacity & Lab acceptance
export function configureCapacity(resourceId: string, capacityUnits: number, cooledCapacityUnits?: number) {
  return request<{ data: { resourceId: string; capacity: Capacity } }>('POST', '/configure-capacity', { resourceId, capacityUnits, cooledCapacityUnits });
}

export function configureLaboratoryAcceptance(laboratoryId: string, sampleTypeId: string, accepts: boolean) {
  return request<{ data: { laboratoryId: string } }>('POST', '/configure-laboratory-acceptance', { laboratoryId, sampleTypeId, accepts });
}

// Serviceability
export function checkServiceability(params: {
  origin: { latitude: number; longitude: number };
  originType?: string;
  originNodeId?: string;
  sampleTypeId: string;
  requestedAt: string;
  deliveryDeadline: string;
  earliestCollectionAt?: string;
  latestCollectionAt?: string;
}) {
  return request<{ data: ServiceabilityResult }>('POST', '/check-serviceability', params);
}

export function readServiceabilitySnapshot() {
  return request<{ data: ServiceabilityRegion[] }>('POST', '/read-serviceability-snapshot');
}

// Collection requests
export function createCollectionRequest(params: {
  requesterId?: string;
  origin: { latitude: number; longitude: number };
  originType?: string;
  originNodeId?: string;
  requestedAt: string;
  deliveryDeadline: string;
  earliestCollectionAt?: string;
  latestCollectionAt?: string;
  sampleTypeId: string;
  containerType: string;
  temperatureMinC: number;
  temperatureMaxC: number;
  incompatibleSampleTypes?: string[];
  idempotencyKey?: string;
}) {
  return request<{ data: { sampleId: string; journeyId: string } }>('POST', '/create-collection-request', params);
}

// Sample lifecycle
export function collectAndSealSample(params: {
  sampleId: string;
  assignmentId: string;
  collectedAt: string;
  containerType: string;
  observedTemperatureC: number;
  idempotencyKey?: string;
}) {
  return request<{ data: { sampleId: string } }>('POST', '/collect-and-seal-sample', params);
}

export function ingestPresealedSample(params: {
  requesterId?: string;
  origin: { latitude: number; longitude: number };
  originType?: string;
  originNodeId?: string;
  requestedAt: string;
  deliveryDeadline: string;
  earliestCollectionAt?: string;
  latestCollectionAt?: string;
  sampleTypeId: string;
  containerType: string;
  temperatureMinC: number;
  temperatureMaxC: number;
  incompatibleSampleTypes?: string[];
  idempotencyKey?: string;
}) {
  return request<{ data: { sampleId: string; journeyId: string } }>('POST', '/ingest-presealed-sample', params);
}

export function readSampleState(sampleId: string) {
  return request<{ data: SampleState }>('GET', `/read-sample-state/${sampleId}`);
}

export function readSampleLifecycle(sampleId: string) {
  return request<{ data: SampleLifecycle }>('POST', '/read-sample-lifecycle', { sampleId });
}

// Assignments
export function acceptAssignment(assignmentId: string, idempotencyKey?: string) {
  return request<{ data: { assignmentId: string; status: string } }>('POST', '/accept-assignment', { assignmentId, idempotencyKey: idempotencyKey || crypto.randomUUID() });
}

export function declineAssignment(assignmentId: string, reason?: string, declinedAt?: string) {
  return request<{ data: { assignmentId: string; status: string } }>('POST', '/decline-assignment', { assignmentId, reason, declinedAt: declinedAt || new Date().toISOString(), idempotencyKey: crypto.randomUUID() });
}

export function updateAssignmentProgress(assignmentId: string, status: string, occurredAt?: string) {
  return request<{ data: { assignmentId: string; status: string } }>('POST', '/update-assignment-progress', { assignmentId, status, occurredAt: occurredAt || new Date().toISOString(), idempotencyKey: crypto.randomUUID() });
}

// Worker location & availability
export function recordWorkerLocation(assignmentId: string, coordinate: { latitude: number; longitude: number }, sequence: number, recordedAt?: string) {
  return request<{ data: { assignmentId: string } }>('POST', '/record-worker-location', { assignmentId, coordinate, sequence, recordedAt: recordedAt || new Date().toISOString() });
}

export function setWorkerAvailability(workerId: string, available: boolean, capacityUnits?: number) {
  return request<{ data: { workerId: string } }>('POST', '/set-worker-availability', { workerId, available, capacityUnits: capacityUnits ?? 0 });
}

// Handoffs
export function initiateHandoff(params: {
  sampleId: string;
  fromAssignmentId: string;
  toAssignmentId: string;
  receiverId: string;
  initiatedAt: string;
  idempotencyKey?: string;
}) {
  return request<{ data: { handoffId: string } }>('POST', '/initiate-handoff', params);
}

export function confirmHandoff(handoffId: string, confirmationSide: 'sender' | 'receiver', confirmedAt?: string) {
  return request<{ data: { handoffId: string; status: string } }>('POST', '/confirm-handoff', { handoffId, confirmationSide, confirmedAt: confirmedAt || new Date().toISOString(), idempotencyKey: crypto.randomUUID() });
}

// Lab
export function confirmLaboratoryReceipt(sampleId: string, laboratoryId: string, receivedAt?: string) {
  return request<{ data: { sampleId: string } }>('POST', '/confirm-laboratory-receipt', { sampleId, laboratoryId, receivedAt: receivedAt || new Date().toISOString(), idempotencyKey: crypto.randomUUID() });
}

export function recordLaboratoryException(sampleId: string, laboratoryId: string, reason: string, observedAt?: string) {
  return request<{ data: { sampleId: string } }>('POST', '/record-laboratory-exception', { sampleId, laboratoryId, reason, observedAt: observedAt || new Date().toISOString(), idempotencyKey: crypto.randomUUID() });
}

// Handling checkpoint
export function recordHandlingCheckpoint(params: {
  sampleId: string;
  assignmentId: string;
  locationId?: string;
  containerType: string;
  observedTemperatureC: number;
  recordedAt: string;
  idempotencyKey?: string;
}) {
  return request<{ data: { sampleId: string } }>('POST', '/record-handling-checkpoint', params);
}

// Journeys
export function readJourneyPlan(journeyId: string) {
  return request<{ data: JourneyPlan | WorkerJourneyPlan | RequesterJourneyPlan }>('POST', '/read-journey-plan', { journeyId });
}

export function cancelJourney(journeyId: string, expectedPlanVersion: number, reason?: string) {
  return request<{ data: { journeyId: string } }>('POST', '/cancel-journey', { journeyId, expectedPlanVersion, reason, idempotencyKey: crypto.randomUUID() });
}

export function editActivePlan(journeyId: string, expectedPlanVersion: number, changeType: string, changes: unknown) {
  return request<{ data: { journeyId: string; planVersion: number } }>('POST', '/edit-active-plan', { journeyId, expectedPlanVersion, changeType, changes, idempotencyKey: crypto.randomUUID() });
}

export function splitJourney(journeyId: string, expectedPlanVersion: number, sampleIds: string[]) {
  return request<{ data: { journeyId: string; childJourneyIds: string[] } }>('POST', '/split-journey', { journeyId, expectedPlanVersion, sampleIds, idempotencyKey: crypto.randomUUID() });
}

export function mergeJourneys(targetJourneyId: string, expectedPlanVersion: number, sourceJourneyIds: string[]) {
  return request<{ data: { journeyId: string; planVersion: number } }>('POST', '/merge-journeys', { targetJourneyId, expectedPlanVersion, sourceJourneyIds, idempotencyKey: crypto.randomUUID() });
}

export function rerouteJourney(journeyId: string, expectedPlanVersion: number, reason?: string) {
  return request<{ data: { journeyId: string; planVersion: number } }>('POST', '/reroute-journey', { journeyId, expectedPlanVersion, reason, idempotencyKey: crypto.randomUUID() });
}

export function reportDisruption(resourceType: string, resourceId: string, occurredAt?: string, reason?: string) {
  return request<{ data: { disruptionId: string } }>('POST', '/report-disruption', { resourceType, resourceId, reason, occurredAt: occurredAt || new Date().toISOString(), idempotencyKey: crypto.randomUUID() });
}

// Role work
export function listRoleWork(role: string, status?: string) {
  return request<{ data: RoleWork }>('POST', '/list-role-work', { role, status });
}

// Ops state
export function readOperationsState(filters?: Record<string, unknown>) {
  return request<{ data: OperationsState }>('POST', '/read-operations-state', { filters: filters || {} });
}

// Audit
export function searchAuditTrail(params: {
  query?: string;
  actorId?: string;
  entityType?: string;
  entityId?: string;
  action?: string;
  role?: string;
  success?: boolean;
  fromTime?: string;
  toTime?: string;
  limit?: number;
  offset?: number;
  order?: string;
}) {
  return request<{ data: AuditSearchResult }>('POST', '/search-audit-trail', params);
}

