import type { AuthUser, BootstrapData, Role } from '../types';
import * as api from '../api/client';

interface AuthState {
  user: AuthUser | null;
  bootstrap: BootstrapData | null;
  login: (username: string, password: string) => Promise<void>;
  logout: () => void;
  switchRole: (role: Role) => Promise<void>;
  refreshBootstrap: () => Promise<void>;
  hasRole: (...roles: Role[]) => boolean;
}

const AuthContext = createContext<AuthState | null>(null);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [bootstrap, setBootstrap] = useState<BootstrapData | null>(null);

  const loginFn = useCallback(async (username: string, password: string) => {
    const res = await api.authenticateUser(username, password);
    const { user: u, token } = res.data;
    api.setSession(token);
    setUser(u);
    const b = await api.readUIBootstrap();
    setBootstrap(b.data);
  }, []);

  const logout = useCallback(() => {
    api.setSession(null);
    api.setActiveRole(null);
    setUser(null);
    setBootstrap(null);
  }, []);

  const switchRole = useCallback(async (role: Role) => {
    await api.selectActiveRole(role);
    api.setActiveRole(role);
    if (user) {
      setUser({ ...user, activeRole: role });
    }
  }, [user]);

  const refreshBootstrap = useCallback(async () => {
    const b = await api.readUIBootstrap();
    setBootstrap(b.data);
  }, []);

  const hasRole = useCallback((...roles: Role[]): boolean => {
    return !!user && roles.some((r) => user.roles.includes(r));
  }, [user]);

  return (
    <AuthContext.Provider value={{ user, bootstrap, login: loginFn, logout, switchRole, refreshBootstrap, hasRole }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth must be inside AuthProvider');
  return ctx;
}

