import { Routes, Route, Navigate } from 'react-router-dom';
import { useAuth } from './context/AuthContext';
import LoginPage from './pages/LoginPage';
import Layout from './components/Layout';
import Dashboard from './pages/Dashboard';
import SampleDetail from './pages/SampleDetail';
import CreateRequest from './pages/CreateRequest';
import ServiceabilityCheck from './pages/ServiceabilityCheck';
import WorkView from './pages/WorkView';
import OperationsMonitor from './pages/OperationsMonitor';
import AuditView from './pages/AuditView';
import AdminPanel from './pages/AdminPanel';
import SampleTypeView from './pages/SampleTypeView';
import LocationView from './pages/LocationView';
import UserView from './pages/UserView';
import MapView from './pages/MapView';

function RequireAuth({ children }: { children: React.ReactElement }) {
  const { user } = useAuth();
  if (!user) return <Navigate to="/login" replace />;
  return children;
}

export default function App() {
  return (
    <Routes>
      <Route path="/login" element={<LoginPage />} />
      <Route
        path="/*"
        element={
          <RequireAuth>
            <Layout>
              <Routes>
                <Route path="/" element={<Dashboard />} />
                <Route path="/dashboard" element={<Dashboard />} />
                <Route path="/samples/:sampleId" element={<SampleDetail />} />
                <Route path="/create-request" element={<CreateRequest />} />
                <Route path="/serviceability" element={<ServiceabilityCheck />} />
                <Route path="/work" element={<WorkView />} />
                <Route path="/operations" element={<OperationsMonitor />} />
                <Route path="/audit" element={<AuditView />} />
                <Route path="/admin" element={<AdminPanel />} />
                <Route path="/admin/sample-types" element={<SampleTypeView />} />
                <Route path="/admin/locations" element={<LocationView />} />
                <Route path="/admin/users" element={<UserView />} />
                <Route path="/map" element={<MapView />} />
                <Route path="*" element={<Navigate to="/dashboard" replace />} />
              </Routes>
            </Layout>
          </RequireAuth>
        }
      />
    </Routes>
  );
}

