import { useLocation, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import type { Role } from '../types';

const NAV_SECTIONS: { section: string; roles: Role[]; items: { label: string; path: string; roles?: Role[] }[] }[] = [
  {
    section: 'Main',
    roles: ['administrator', 'dispatcher', 'requester', 'collection_professional', 'delivery_partner', 'node_handler', 'laboratory_team'],
    items: [
      { label: 'Dashboard', path: '/dashboard' },
      { label: 'My Work', path: '/work', roles: ['requester', 'collection_professional', 'delivery_partner', 'node_handler', 'laboratory_team'] },
      { label: 'Map', path: '/map' },
      { label: 'Create Request', path: '/create-request', roles: ['requester'] },
      { label: 'Serviceability', path: '/serviceability', roles: ['requester'] },
    ],
  },
  {
    section: 'Operations',
    roles: ['administrator', 'dispatcher'],
    items: [
      { label: 'Monitor', path: '/operations' },
      { label: 'Audit Trail', path: '/audit' },
    ],
  },
  {
    section: 'Admin',
    roles: ['administrator'],
    items: [
      { label: 'Settings', path: '/admin' },
      { label: 'Sample Types', path: '/admin/sample-types' },
      { label: 'Locations', path: '/admin/locations' },
      { label: 'Users', path: '/admin/users' },
    ],
  },
];

export default function Layout({ children }: { children: React.ReactNode }) {
  const { user, switchRole, logout, hasRole } = useAuth();
  const location = useLocation();
  const navigate = useNavigate();

  const isActive = (path: string) => location.pathname === path || (path !== '/' && location.pathname.startsWith(path));

  return (
    <div className="layout">
      <nav className="sidebar">
        <div className="flex-between mb-2">
          <h2 style={{ fontSize: '1rem' }}>🧪 Lab Samples</h2>
        </div>
        {(user?.roles?.length ?? 0) > 1 && (
          <div className="role-switcher mb-2">
            <select
              value={user?.activeRole || ''}
              onChange={(e) => switchRole(e.target.value as Role)}
            >
              {user?.roles?.map((r) => (
                <option key={r} value={r}>
                  {r.replace(/_/g, ' ')}
                </option>
              ))}
            </select>
          </div>
        )}
        <div className="text-sm text-secondary mb-1">
          {user?.fullName || user?.username} • {user?.activeRole?.replace(/_/g, ' ')}
        </div>
        <div className="flex-col gap-1" style={{ flex: 1 }}>
          {NAV_SECTIONS.map((section) => {
            if (!section.roles.some((r) => hasRole(r))) return null;
            return (
              <div key={section.section}>
                <div className="nav-section">{section.section}</div>
                {section.items.map((item) => {
                  if (item.roles && !item.roles.some((r) => hasRole(r))) return null;
                  return (
                    <button
                      key={item.path}
                      className={`nav-item ${isActive(item.path) ? 'active' : ''}`}
                      onClick={() => navigate(item.path)}
                    >
                      {item.label}
                    </button>
                  );
                })}
              </div>
            );
          })}
        </div>
        <button className="btn btn-sm" onClick={logout}>
          Sign Out
        </button>
      </nav>
      <main className="main-content">{children}</main>
    </div>
  );
}

