import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { listRoleWork, readSampleState } from '../api/client';
import type { SampleWorkItem, AssignmentWorkItem, JourneyWorkItem } from '../types';

type WorkItem = SampleWorkItem | AssignmentWorkItem | JourneyWorkItem;

export default function Dashboard() {
  const { user, hasRole } = useAuth();
  const navigate = useNavigate();
  const [work, setWork] = useState<{ pending: WorkItem[]; inProgress: WorkItem[] }>({ pending: [], inProgress: [] });
  const [loading, setLoading] = useState(true);
  const role = user?.activeRole || '';

  useEffect(() => {
    if (!role) return;
    (async () => {
      try {
        const res = await listRoleWork(role);
        setWork({ pending: res.data.pending as WorkItem[], inProgress: res.data.inProgress as WorkItem[] });
      } catch { /* ignore */ }
      setLoading(false);
    })();
  }, [role]);

  const isSample = (w: WorkItem): w is SampleWorkItem => w.kind === 'sample';
  const isAssignment = (w: WorkItem): w is AssignmentWorkItem => w.kind === 'collection' || w.kind === 'transport' || w.kind === 'node' || w.kind === 'laboratory';
  const isJourney = (w: WorkItem): w is JourneyWorkItem => w.kind === 'journey';

  return (
    <div>
      <div className="page-header">
        <h1 className="page-title">Dashboard</h1>
        <span className="text-secondary">Role: {role.replace(/_/g, ' ')}</span>
      </div>

      {loading ? (
        <p className="text-secondary">Loading...</p>
      ) : (
        <div className="grid grid-2">
          <div>
            <h2 className="mb-2">Pending Work ({work.pending.length})</h2>
            <div className="flex-col gap-1">
              {work.pending.length === 0 && <p className="text-sm text-secondary">No pending work</p>}
              {work.pending.map((w) => (
                <div key={w.kind + getItemId(w)} className="card" style={{ padding: '0.75rem' }}>
                  <div className="flex-between">
                    <div>
                      <span className="badge badge-pending">{w.kind}</span>
                      {' '}
                      <span className="font-bold">{getItemId(w).slice(0, 8)}...</span>
                    </div>
                    <span className={`badge ${w.status === 'offered' ? 'badge-pending' : 'badge-active'}`}>
                      {w.status}
                    </span>
                  </div>
                  {isSample(w) && (
                    <div className="text-sm text-secondary mt-1">
                      Request: {w.requestId?.slice(0, 8)}... | Deadline: {w.deliveryDeadline ? new Date(w.deliveryDeadline).toLocaleString() : '—'}
                    </div>
                  )}
                  {isAssignment(w) && (
                    <div className="text-sm text-secondary mt-1">
                      From: {w.fromLocationId?.slice(0, 8) || '—'} → To: {w.toLocationId?.slice(0, 8) || '—'}
                    </div>
                  )}
                  <button
                    className="btn btn-sm btn-primary mt-1"
                    onClick={() => isSample(w) && navigate(`/samples/${w.sampleId}`)}
                  >
                    View
                  </button>
                </div>
              ))}
            </div>
          </div>

          <div>
            <h2 className="mb-2">In Progress ({work.inProgress.length})</h2>
            <div className="flex-col gap-1">
              {work.inProgress.length === 0 && <p className="text-sm text-secondary">No work in progress</p>}
              {work.inProgress.map((w) => (
                <div key={w.kind + getItemId(w)} className="card" style={{ padding: '0.75rem' }}>
                  <div className="flex-between">
                    <div>
                      <span className="badge badge-active">{w.kind}</span>
                      {' '}
                      <span className="font-bold">{getItemId(w).slice(0, 8)}...</span>
                    </div>
                    <span className="badge badge-active">{w.status}</span>
                  </div>
                  {isSample(w) && (
                    <div className="text-sm text-secondary mt-1">
                      Lab: {w.laboratoryId?.slice(0, 8) || '—'} | {w.locationStale ? '⚠ Stale' : '✓ Fresh'}
                    </div>
                  )}
                  <button
                    className="btn btn-sm btn-primary mt-1"
                    onClick={() => isSample(w) ? navigate(`/samples/${w.sampleId}`) : null}
                  >
                    View
                  </button>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {hasRole('administrator', 'dispatcher') && (
        <div className="mt-2">
          <button className="btn btn-primary" onClick={() => navigate('/operations')}>
            Operations Monitor
          </button>
        </div>
      )}
    </div>
  );
}

function getItemId(w: WorkItem): string {
  return (
    (w as SampleWorkItem).sampleId ||
    (w as AssignmentWorkItem).assignmentId ||
    (w as JourneyWorkItem).journeyId ||
    ''
  );
}

