import { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import { readSampleState, readSampleLifecycle, readJourneyPlan, acceptAssignment, declineAssignment, confirmHandoff, initiateHandoff, confirmLaboratoryReceipt, recordHandlingCheckpoint } from '../api/client';
import type { SampleState, SampleLifecycle, JourneyPlan, WorkerJourneyPlan, RequesterJourneyPlan, AssignmentWorkItem } from '../types';
import { useAuth } from '../context/AuthContext';

export default function SampleDetail() {
  const { sampleId } = useParams<{ sampleId: string }>();
  const { user, hasRole } = useAuth();
  const [state, setState] = useState<SampleState | null>(null);
  const [lifecycle, setLifecycle] = useState<SampleLifecycle | null>(null);
  const [journey, setJourney] = useState<JourneyPlan | WorkerJourneyPlan | RequesterJourneyPlan | null>(null);
  const [activeTab, setActiveTab] = useState<'info' | 'lifecycle' | 'journey'>('info');
  const [actionMsg, setActionMsg] = useState('');
  const [confirmSender, setConfirmSender] = useState(false);
  const [confirmReceiver, setConfirmReceiver] = useState(false);

  useEffect(() => {
    if (!sampleId) return;
    load();
  }, [sampleId]);

  async function load() {
    try {
      const [s, l] = await Promise.all([
        readSampleState(sampleId!),
        readSampleLifecycle(sampleId!),
      ]);
      setState(s.data);
      setLifecycle(l.data);
      if (s.data.activeJourneyId) {
        try {
          const j = await readJourneyPlan(s.data.activeJourneyId);
          setJourney(j.data);
        } catch { /* ignore */ }
      }
    } catch { /* ignore */ }
  }

  async function handleAccept(asstId: string) {
    try {
      await acceptAssignment(asstId);
      setActionMsg('Assignment accepted');
      load();
    } catch (e: unknown) { setActionMsg(e instanceof Error ? e.message : 'Error'); }
  }

  async function handleDecline(asstId: string) {
    try {
      await declineAssignment(asstId);
      setActionMsg('Assignment declined');
      load();
    } catch (e: unknown) { setActionMsg(e instanceof Error ? e.message : 'Error'); }
  }

  async function handleHandoffInitiate(toAsstId: string, receiverId: string) {
    try {
      await initiateHandoff({
        sampleId: sampleId!,
        fromAssignmentId: state?.activeAssignmentIds?.[0] || '',
        toAssignmentId: toAsstId,
        receiverId,
        initiatedAt: new Date().toISOString(),
      });
      setActionMsg('Handoff initiated');
      load();
    } catch (e: unknown) { setActionMsg(e instanceof Error ? e.message : 'Error'); }
  }

  async function handleHandoffConfirm(handoffId: string, side: 'sender' | 'receiver') {
    try {
      await confirmHandoff(handoffId, side);
      setActionMsg(`Handoff confirmed by ${side}`);
      load();
    } catch (e: unknown) { setActionMsg(e instanceof Error ? e.message : 'Error'); }
  }

  async function handleLabReceipt(labId: string) {
    try {
      await confirmLaboratoryReceipt(sampleId!, labId);
      setActionMsg('Lab receipt confirmed');
      load();
    } catch (e: unknown) { setActionMsg(e instanceof Error ? e.message : 'Error'); }
  }

  if (!state) return <p className="text-secondary">Loading sample...</p>;

  return (
    <div>
      <div className="page-header">
        <h1 className="page-title">Sample {sampleId?.slice(0, 8)}...</h1>
        <div className="flex gap-2">
          <span className={`badge ${state.status === 'expired' || state.exception ? 'badge-exception' : state.status === 'delivered' ? 'badge-complete' : 'badge-active'}`}>
            {state.state?.status as string || state.status || 'unknown'}
          </span>
          {state.locationStale && <span className="badge badge-stale">STALE</span>}
        </div>
      </div>

      {actionMsg && (
        <div className="card mb-2" style={{ padding: '0.5rem 1rem', background: '#f0fdf4' }}>{actionMsg}</div>
      )}

      <div className="flex gap-1 mb-2">
        {['info', 'lifecycle', 'journey'].map((tab) => (
          <button key={tab} className={`btn btn-sm ${activeTab === tab ? 'btn-primary' : ''}`} onClick={() => setActiveTab(tab as typeof activeTab)}>
            {tab.charAt(0).toUpperCase() + tab.slice(1)}
          </button>
        ))}
      </div>

      {activeTab === 'info' && (
        <div className="grid grid-2">
          <div className="card" style={{ padding: '1rem' }}>
            <h3 className="mb-2">Details</h3>
            <div className="flex-col gap-1 text-sm">
              <div><strong>Sample ID:</strong> {state.sampleId}</div>
              <div><strong>Request ID:</strong> {state.requestId}</div>
              <div><strong>Type:</strong> {state.sampleTypeId}</div>
              <div><strong>Container:</strong> {state.containerType}</div>
              <div><strong>Temp Range:</strong> {state.temperatureMinC}°C – {state.temperatureMaxC}°C</div>
              <div><strong>Origin:</strong> {state.originType} @ {state.origin.latitude?.toFixed(4)}, {state.origin.longitude?.toFixed(4)}</div>
              <div><strong>Serviceability:</strong> {state.serviceability}</div>
              <div><strong>Deadline:</strong> {new Date(state.deliveryDeadline).toLocaleString()}</div>
              {state.targetLaboratoryId && <div><strong>Target Lab:</strong> {state.targetLaboratoryId}</div>}
              {state.activeJourneyId && <div><strong>Active Journey:</strong> {state.activeJourneyId}</div>}
              {state.earliestCollectionAt && <div><strong>Earliest Coll:</strong> {new Date(state.earliestCollectionAt).toLocaleString()}</div>}
              {state.latestCollectionAt && <div><strong>Latest Coll:</strong> {new Date(state.latestCollectionAt).toLocaleString()}</div>}
            </div>
          </div>

          <div className="card" style={{ padding: '1rem' }}>
            <h3 className="mb-2">Actions</h3>
            <div className="flex-col gap-1">
              {state.activeAssignmentIds?.map((aid) => (
                <div key={aid} className="flex-between text-sm">
                  <span>Assignment: {aid.slice(0, 12)}...</span>
                  <div className="flex gap-1">
                    <button className="btn btn-sm btn-primary" onClick={() => handleAccept(aid)}>Accept</button>
                    <button className="btn btn-sm btn-danger" onClick={() => handleDecline(aid)}>Decline</button>
                  </div>
                </div>
              ))}
              {lifecycle?.pendingHandoffId && (
                <div className="flex-col gap-1 mt-1">
                  <div className="text-sm font-bold">Pending Handoff: {lifecycle.pendingHandoffId.slice(0, 12)}...</div>
                  <div className="flex gap-1">
                    <button className="btn btn-sm btn-primary" onClick={() => handleHandoffConfirm(lifecycle.pendingHandoffId!, 'sender')}>Confirm as Sender</button>
                    <button className="btn btn-sm btn-primary" onClick={() => handleHandoffConfirm(lifecycle.pendingHandoffId!, 'receiver')}>Confirm as Receiver</button>
                  </div>
                </div>
              )}
              {hasRole('laboratory_team') && state.targetLaboratoryId && (
                <button className="btn btn-sm btn-primary mt-1" onClick={() => handleLabReceipt(state.targetLaboratoryId!)}>
                  Confirm Lab Receipt
                </button>
              )}
            </div>
          </div>
        </div>
      )}

      {activeTab === 'lifecycle' && lifecycle && (
        <div className="card" style={{ padding: '1rem' }}>
          <h3 className="mb-2">Timeline</h3>
          <ul className="timeline">
            {lifecycle.timeline?.map((t, i) => (
              <li key={i}>
                <div>
                  <span className="font-bold">{t.action}</span>
                  <span className="text-sm text-secondary"> by {t.role} ({t.actorId?.slice(0, 8)}...)</span>
                </div>
                <div className="text-sm text-secondary">
                  {new Date(t.occurredAt).toLocaleString()}
                  {!t.success && ' ❌'}
                </div>
              </li>
            ))}
          </ul>
        </div>
      )}

      {activeTab === 'journey' && journey && (
        <div className="card" style={{ padding: '1rem' }}>
          <h3 className="mb-2">Journey Plan (v{journey.planVersion})</h3>
          <div className="text-sm mb-2">
            <div><strong>Route Mode:</strong> {journey.routeMode}</div>
            <div><strong>Status:</strong> {journey.status}</div>
            <div><strong>Est Delivery:</strong> {journey.estimatedDeliveryAt ? new Date(journey.estimatedDeliveryAt).toLocaleString() : '—'}</div>
            <div><strong>Samples:</strong> {journey.sampleIds?.join(', ')}</div>
          </div>
          <h4 className="mb-1">Legs</h4>
          <table className="table">
            <thead>
              <tr>
                <th>Seq</th>
                <th>Status</th>
                <th>From</th>
                <th>To</th>
                <th>Worker</th>
              </tr>
            </thead>
            <tbody>
              {journey.legs?.map((leg) => (
                <tr key={leg.assignmentId}>
                  <td>{leg.sequence}</td>
                  <td><span className="badge badge-active">{leg.status}</span></td>
                  <td>{leg.fromLocationId?.slice(0, 8)}...</td>
                  <td>{leg.toLocationId?.slice(0, 8)}...</td>
                  <td>{leg.workerId?.slice(0, 8) || '—'}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

