import { useState, type FormEvent } from 'react';
import { useNavigate } from 'react-router-dom';
import { createCollectionRequest, checkServiceability } from '../api/client';
import { useAuth } from '../context/AuthContext';
import type { SampleType } from '../types';

export default function CreateRequest() {
  const { user, bootstrap } = useAuth();
  const navigate = useNavigate();
  const [originLat, setOriginLat] = useState('');
  const [originLng, setOriginLng] = useState('');
  const [originType, setOriginType] = useState('home');
  const [originNodeId, setOriginNodeId] = useState('');
  const [sampleTypeId, setSampleTypeId] = useState('');
  const [containerType, setContainerType] = useState('standard');
  const [tempMin, setTempMin] = useState('0');
  const [tempMax, setTempMax] = useState('30');
  const [deadline, setDeadline] = useState('');
  const [earliestCol, setEarliestCol] = useState('');
  const [latestCol, setLatestCol] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const sampleTypes: SampleType[] = bootstrap?.sampleTypes || [];

  async function handleCheck() {
    setError('');
    try {
      const res = await checkServiceability({
        origin: { latitude: parseFloat(originLat), longitude: parseFloat(originLng) },
        originType,
        originNodeId: originNodeId || undefined,
        sampleTypeId,
        requestedAt: new Date().toISOString(),
        deliveryDeadline: new Date(deadline).toISOString(),
        earliestCollectionAt: earliestCol ? new Date(earliestCol).toISOString() : undefined,
        latestCollectionAt: latestCol ? new Date(latestCol).toISOString() : undefined,
      });
      setSuccess(`Serviceable: ${res.data.serviceable}${res.data.reason ? ' - ' + res.data.reason : ''}`);
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : 'Check failed');
    }
  }

  async function handleSubmit(e: FormEvent) {
    e.preventDefault();
    setError('');
    setSuccess('');
    try {
      const res = await createCollectionRequest({
        origin: { latitude: parseFloat(originLat), longitude: parseFloat(originLng) },
        originType,
        originNodeId: originNodeId || undefined,
        requestedAt: new Date().toISOString(),
        deliveryDeadline: new Date(deadline).toISOString(),
        earliestCollectionAt: earliestCol ? new Date(earliestCol).toISOString() : undefined,
        latestCollectionAt: latestCol ? new Date(latestCol).toISOString() : undefined,
        sampleTypeId,
        containerType,
        temperatureMinC: parseFloat(tempMin),
        temperatureMaxC: parseFloat(tempMax),
        idempotencyKey: crypto.randomUUID(),
      });
      setSuccess(`Request created! Sample: ${(res.data as {sampleId: string}).sampleId}`);
      setTimeout(() => navigate(`/samples/${(res.data as {sampleId: string}).sampleId}`), 1000);
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : 'Creation failed');
    }
  }

  return (
    <div>
      <div className="page-header">
        <h1 className="page-title">Create Collection Request</h1>
      </div>

      <div className="card" style={{ padding: '1.5rem', maxWidth: '600px' }}>
        <form onSubmit={handleSubmit} className="flex-col gap-2">
          <div className="grid grid-2">
            <div className="form-group">
              <label>Origin Latitude</label>
              <input type="number" step="any" value={originLat} onChange={e => setOriginLat(e.target.value)} required />
            </div>
            <div className="form-group">
              <label>Origin Longitude</label>
              <input type="number" step="any" value={originLng} onChange={e => setOriginLng(e.target.value)} required />
            </div>
          </div>

          <div className="grid grid-2">
            <div className="form-group">
              <label>Origin Type</label>
              <select value={originType} onChange={e => setOriginType(e.target.value)}>
                <option value="home">Home</option>
                <option value="clinic">Clinic</option>
                <option value="node">Node</option>
