import { useEffect, useState } from 'react';
import { useAuth } from '../context/AuthContext';
import { createSampleType, updateSampleType, readUIBootstrap } from '../api/client';
import type { SampleType } from '../types';

export default function SampleTypeView() {
  const { bootstrap, refreshBootstrap } = useAuth();
  const [types, setTypes] = useState<SampleType[]>([]);
  const [showNew, setShowNew] = useState(false);
  const [editId, setEditId] = useState<string | null>(null);
  const [name, setName] = useState('');
  const [container, setContainer] = useState('standard');
  const [tempMin, setTempMin] = useState('0');
  const [tempMax, setTempMax] = useState('30');
  const [cooled, setCooled] = useState(false);
  const [batch, setBatch] = useState(true);
  const [collectorReq, setCollectorReq] = useState(false);
  const [qualification, setQualification] = useState('');
  const [msg, setMsg] = useState('');

  useEffect(() => {
    if (bootstrap?.sampleTypes) setTypes(bootstrap.sampleTypes);
  }, [bootstrap]);

  async function handleCreate() {
    try {
      await createSampleType({ name, containerType: container, temperatureMinC: parseFloat(tempMin), temperatureMaxC: parseFloat(tempMax), requiresCooledRoute: cooled, batchingAllowed: batch, qualifiedCollectorRequired: collectorReq, requiredQualification: qualification });
      setMsg('Created');
      await refreshBootstrap();
      setShowNew(false);
    } catch (e: unknown) { setMsg(e instanceof Error ? e.message : 'Error'); }
  }

  async function handleUpdate() {
    try {
      await updateSampleType({ sampleTypeId: editId!, containerType: container, temperatureMinC: parseFloat(tempMin), temperatureMaxC: parseFloat(tempMax), requiresCooledRoute: cooled, batchingAllowed: batch, qualifiedCollectorRequired: collectorReq, requiredQualification: qualification });
      setMsg('Updated');
      await refreshBootstrap();
      setEditId(null);
    } catch (e: unknown) { setMsg(e instanceof Error ? e.message : 'Error'); }
  }

  function startEdit(t: SampleType) {
    setEditId(t.sampleTypeId);
    setName(t.name);
    setContainer(t.containerType);
    setTempMin(String(t.temperatureMinC));
    setTempMax(String(t.temperatureMaxC));
    setCooled(t.requiresCooledRoute);
    setBatch(t.batchingAllowed);
    setCollectorReq(t.qualifiedCollectorRequired);
    setQualification(t.requiredQualification);
  }

  return (
    <div>
      <div className="page-header">
        <h1 className="page-title">Sample Types</h1>
        <button className="btn btn-primary" onClick={() => setShowNew(true)}>New Type</button>
      </div>

      {msg && <div className="card mb-2" style={{ padding: '0.5rem 1rem' }}>{msg}</div>}

      {(showNew || editId) && (
        <div className="card mb-2" style={{ padding: '1rem' }}>
          <h3 className="mb-2">{showNew ? 'New Sample Type' : 'Edit Sample Type'}</h3>
          <div className="grid grid-3">
            <div className="form-group">
              <label>Name</label>
              <input value={name} onChange={e => setName(e.target.value)} disabled={!!editId} />
            </div>
            <div className="form-group">
              <label>Container Type</label>
              <input value={container} onChange={e => setContainer(e.target.value)} />
            </div>
            <div className="form-group">
              <label>Qualification</label>
              <input value={qualification} onChange={e => setQualification(e.target.value)} placeholder="If collector required" />
            </div>
            <div className="form-group">
              <label>Temp Min (°C)</label>
              <input type="number" step="any" value={tempMin} onChange={e => setTempMin(e.target.value)} />
            </div>
            <div className="form-group">
              <label>Temp Max (°C)</label>
              <input type="number" step="any" value={tempMax} onChange={e => setTempMax(e.target.value)} />
            </div>
          </div>
          <div className="flex gap-2 mt-2">
            <label className="text-sm"><input type="checkbox" checked={cooled} onChange={e => setCooled(e.target.checked)} /> Requires Cooled</label>
            <label className="text-sm"><input type="checkbox" checked={batch} onChange={e => setBatch(e.target.checked)} /> Batching Allowed</label>
            <label className="text-sm"><input type="checkbox" checked={collectorReq} onChange={e => setCollectorReq(e.target.checked)} /> Qualified Collector Required</label>
          </div>
          <div className="flex gap-1 mt-2">
            {showNew && <button className="btn btn-primary" onClick={handleCreate}>Create</button>}
            {editId && <button className="btn btn-primary" onClick={handleUpdate}>Update</button>}
            <button className="btn" onClick={() => { setShowNew(false); setEditId(null); }}>Cancel</button>
          </div>
        </div>
      )}

      <div className="card" style={{ padding: '1rem' }}>
        <table className="table">
          <thead>
            <tr><th>Name</th><th>Container</th><th>Temp Range</th><th>Cooled</th><th>Batch</th><th>Collector Req.</th><th></th></tr>
          </thead>
          <tbody>
            {types.map((t) => (
              <tr key={t.sampleTypeId}>
                <td className="font-bold">{t.name}</td>
                <td>{t.containerType}</td>
                <td>{t.temperatureMinC}–{t.temperatureMaxC}°C</td>
                <td>{t.requiresCooledRoute ? '✓' : '—'}</td>
                <td>{t.batchingAllowed ? '✓' : '—'}</td>
                <td>{t.qualifiedCollectorRequired ? `${t.requiredQualification}` : '—'}</td>
                <td><button className="btn btn-sm" onClick={() => startEdit(t)}>Edit</button></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

