import { useEffect, useState } from 'react';
import { createLocation, updateLocation, setLocationStatus, setLocationFunctionStatus, createConnection, setConnectionStatus, configureCapacity } from '../api/client';
import { readUIBootstrap } from '../api/client';
import { useAuth } from '../context/AuthContext';
import type { Location, Connection, ConnectionType } from '../types';

export default function LocationView() {
  const { bootstrap, refreshBootstrap, hasRole } = useAuth();
  const [locations, setLocations] = useState<Location[]>([]);
  const [connections, setConnections] = useState<ConnectionType[]>([]);
  const [tab, setTab] = useState<'locations' | 'connections'>('locations');
  const [showNewLoc, setShowNewLoc] = useState(false);
  const [showNewConn, setShowNewConn] = useState(false);
  const [msg, setMsg] = useState('');

  // Location form
  const [locName, setLocName] = useState('');
  const [locLat, setLocLat] = useState('');
  const [locLng, setLocLng] = useState('');
  const [locCov, setLocCov] = useState('5');
  const [locHand, setLocHand] = useState('15');
  const [locCollection, setLocCollection] = useState(false);
  const [locTransfer, setLocTransfer] = useState(false);
  const [locLab, setLocLab] = useState(false);

  // Connection form
  const [connFrom, setConnFrom] = useState('');
  const [connTo, setConnTo] = useState('');
  const [connMinutes, setConnMinutes] = useState('30');
  const [connCost, setConnCost] = useState('1');
  const [connCooled, setConnCooled] = useState(false);

  useEffect(() => {
    if (bootstrap) {
      setLocations(bootstrap.locations || []);
      setConnections(bootstrap.connections || []);
    }
  }, [bootstrap]);

  async function handleCreateLoc() {
    try {
      await createLocation({
        name: locName,
        coordinate: { latitude: parseFloat(locLat), longitude: parseFloat(locLng) },
        coverageKm: parseFloat(locCov),
        handlingMinutes: parseFloat(locHand),
        active: true,
        functions: { collection: locCollection, transfer: locTransfer, laboratory: locLab },
      });
      setMsg('Location created');
      await refreshBootstrap();
      setShowNewLoc(false);
    } catch (e: unknown) { setMsg(e instanceof Error ? e.message : 'Error'); }
  }

  async function handleToggleLoc(locId: string, active: boolean) {
    try {
      await setLocationStatus(locId, !active);
      await refreshBootstrap();
    } catch (e: unknown) { setMsg(e instanceof Error ? e.message : 'Error'); }
  }

  async function handleToggleFunc(locId: string, func: string, active: boolean) {
    try {
      await setLocationFunctionStatus(locId, func, !active);
      await refreshBootstrap();
    } catch (e: unknown) { setMsg(e instanceof Error ? e.message : 'Error'); }
  }

  async function handleCreateConn() {
    try {
      await createConnection({
        fromLocationId: connFrom,
        toLocationId: connTo,
        travelMinutes: parseFloat(connMinutes),
        costUnits: parseFloat(connCost),
        cooled: connCooled,
        active: true,
      });
      setMsg('Connection created');
      await refreshBootstrap();
      setShowNewConn(false);
    } catch (e: unknown) { setMsg(e instanceof Error ? e.message : 'Error'); }
  }

  async function handleToggleConn(connId: string, active: boolean) {
    try {
      await setConnectionStatus(connId, !active);
      await refreshBootstrap();
    } catch (e: unknown) { setMsg(e instanceof Error ? e.message : 'Error'); }
  }

  async function handleCapConfig(locId: string) {
    const units = prompt('Capacity units:');
    const cooled = prompt('Cooled capacity:');
    if (!units) return;
    try {
      await configureCapacity(locId, parseInt(units), cooled ? parseInt(cooled) : undefined);
      setMsg('Capacity configured');
      await refreshBootstrap();
    } catch (e: unknown) { setMsg(e instanceof Error ? e.message : 'Error'); }
  }

  return (
    <div>
      <div className="page-header">
        <h1 className="page-title">Network Locations</h1>
      </div>

      {msg && <div className="card mb-2" style={{ padding: '0.5rem 1rem' }}>{msg}</div>}

      <div className="flex gap-1 mb-2">
        <button className={`btn btn-sm ${tab === 'locations' ? 'btn-primary' : ''}`} onClick={() => setTab('locations')}>
          Locations ({locations.length})
        </button>
        <button className={`btn btn-sm ${tab === 'connections' ? 'btn-primary' : ''}`} onClick={() => setTab('connections')}>
          Connections ({connections.length})
        </button>
      </div>

      {tab === 'locations' && (
        <>
          <div className="flex-between mb-2">
            <span></span>
            <button className="btn btn-primary btn-sm" onClick={() => setShowNewLoc(true)}>Add Location</button>
          </div>

          {showNewLoc && (
            <div className="card mb-2" style={{ padding: '1rem' }}>
              <h3 className="mb-2">New Location</h3>
              <div className="grid grid-3">
                <div className="form-group"><label>Name</label><input value={locName} onChange={e => setLocName(e.target.value)} /></div>
                <div className="form-group"><label>Latitude</label><input type="number" step="any" value={locLat} onChange={e => setLocLat(e.target.value)} /></div>
                <div className="form-group"><label>Longitude</label><input type="number" step="any" value={locLng} onChange={e => setLocLng(e.target.value)} /></div>
                <div className="form-group"><label>Coverage (km)</label><input type="number" step="any" value={locCov} onChange={e => setLocCov(e.target.value)} /></div>
                <div className="form-group"><label>Handling (min)</label><input type="number" step="any" value={locHand} onChange={e => setLocHand(e.target.value)} /></div>
              </div>
              <div className="flex gap-2 mt-2">
                <label className="text-sm"><input type="checkbox" checked={locCollection} onChange={e => setLocCollection(e.target.checked)} /> Collection</label>
                <label className="text-sm"><input type="checkbox" checked={locTransfer} onChange={e => setLocTransfer(e.target.checked)} /> Transfer/Hub</label>
                <label className="text-sm"><input type="checkbox" checked={locLab} onChange={e => setLocLab(e.target.checked)} /> Laboratory</label>
              </div>
              <div className="flex gap-1 mt-2">
                <button className="btn btn-primary" onClick={handleCreateLoc}>Create</button>
                <button className="btn" onClick={() => setShowNewLoc(false)}>Cancel</button>
              </div>
            </div>
          )}

          <div style={{ maxHeight: '500px', overflow: 'auto' }}>
            <table className="table">
              <thead>
                <tr><th>Name</th><th>Coordinate</th><th>Active</th><th>Collection</th><th>Transfer</th><th>Lab</th><th>Capacity</th><th></th></tr>
              </thead>
              <tbody>
                {locations.map((loc) => (
                  <tr key={loc.locationId || loc.id}>
                    <td className="font-bold">{loc.name}</td>
                    <td className="text-sm">{loc.coordinate?.latitude?.toFixed(3)}, {loc.coordinate?.longitude?.toFixed(3)}</td>
                    <td>
                      <button className={`btn btn-sm ${loc.active ? 'btn-primary' : 'btn-danger'}`} onClick={() => handleToggleLoc(loc.locationId || loc.id!, loc.active)}>
                        {loc.active ? 'Active' : 'Inactive'}
                      </button>
                    </td>
                    <td>
                      <button className={`btn btn-sm ${loc.functions?.collection ? 'btn-primary' : ''}`} onClick={() => handleToggleFunc(loc.locationId || loc.id!, 'collection', loc.functions?.collection)}>
                        {loc.functions?.collection ? 'On' : 'Off'}
                      </button>
                    </td>
                    <td>
                      <button className={`btn btn-sm ${loc.functions?.transfer ? 'btn-primary' : ''}`} onClick={() => handleToggleFunc(loc.locationId || loc.id!, 'transfer', loc.functions?.transfer)}>
                        {loc.functions?.transfer ? 'On' : 'Off'}
                      </button>
                    </td>
                    <td>
                      <button className={`btn btn-sm ${loc.functions?.laboratory ? 'btn-primary' : ''}`} onClick={() => handleToggleFunc(loc.locationId || loc.id!, 'laboratory', loc.functions?.laboratory)}>
                        {loc.functions?.laboratory ? 'On' : 'Off'}
                      </button>
                    </td>
                    <td className="text-sm">
                      {loc.capacity ? `${loc.capacity.capacityUnits || 0}u` : '—'}
                    </td>
                    <td>
                      <button className="btn btn-sm" onClick={() => handleCapConfig(loc.locationId || loc.id!)}>Capacity</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </>
      )}

      {tab === 'connections' && (
        <>
          <div className="flex-between mb-2">
            <span></span>
            <button className="btn btn-primary btn-sm" onClick={() => setShowNewConn(true)}>Add Connection</button>
          </div>

          {showNewConn && (
            <div className="card mb-2" style={{ padding: '1rem' }}>
              <h3 className="mb-2">New Connection</h3>
              <div className="grid grid-2">
                <div className="form-group">
                  <label>From</label>
                  <select value={connFrom} onChange={e => setConnFrom(e.target.value)}>
                    <option value="">— Select —</option>
                    {locations.map(l => <option key={l.locationId || l.id} value={l.locationId || l.id}>{l.name}</option>)}
                  </select>
                </div>
                <div className="form-group">
                  <label>To</label>
                  <select value={connTo} onChange={e => setConnTo(e.target.value)}>
                    <option value="">— Select —</option>
                    {locations.map(l => <option key={l.locationId || l.id} value={l.locationId || l.id}>{l.name}</option>)}
                  </select>
                </div>
                <div className="form-group"><label>Travel (min)</label><input type="number" value={connMinutes} onChange={e => setConnMinutes(e.target.value)} /></div>
                <div className="form-group"><label>Cost</label><input type="number" value={connCost} onChange={e => setConnCost(e.target.value)} /></div>
              </div>
              <div className="flex gap-2 mt-2">
                <label className="text-sm"><input type="checkbox" checked={connCooled} onChange={e => setConnCooled(e.target.checked)} /> Cooled</label>
              </div>
              <div className="flex gap-1 mt-2">
                <button className="btn btn-primary" onClick={handleCreateConn}>Create</button>
                <button className="btn" onClick={() => setShowNewConn(false)}>Cancel</button>
              </div>
            </div>
          )}

          <div style={{ maxHeight: '500px', overflow: 'auto' }}>
            <table className="table">
              <thead>
                <tr><th>From</th><th>To</th><th>Time</th><th>Cost</th><th>Cooled</th><th>Active</th><th></th></tr>
              </thead>
              <tbody>
                {connections.map((conn) => (
                  <tr key={conn.connectionId || conn.id}>
                    <td className="text-sm">{conn.fromLocationId?.slice(0, 8)}...</td>
                    <td className="text-sm">{conn.toLocationId?.slice(0, 8)}...</td>
                    <td>{conn.travelMinutes}m</td>
                    <td>{conn.costUnits}</td>
                    <td>{conn.cooled ? '✓' : '—'}</td>
                    <td>
                      <button
                        className={`btn btn-sm ${conn.active ? 'btn-primary' : 'btn-danger'}`}
                        onClick={() => handleToggleConn(conn.connectionId || conn.id!, conn.active)}
                      >
                        {conn.active ? 'Active' : 'Inactive'}
                      </button>
                    </td>
                    <td>
                      <button className="btn btn-sm" onClick={() => configureCapacity(conn.connectionId || conn.id!, 10).then(() => refreshBootstrap())}>Capacity</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </>
      )}
    </div>
  );
}

