                      {loc.capacity ? `${loc.capacity.capacityUnits || 0}u` : '—'}
                    </td>
                    <td>
                      <button className="btn btn-sm" onClick={() => handleCapConfig(loc.locationId || loc.id!)}>Capacity</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </>
      )}

      {tab === 'connections' && (
        <>
          <div className="flex-between mb-2">
            <span></span>
            <button className="btn btn-primary btn-sm" onClick={() => setShowNewConn(true)}>Add Connection</button>
          </div>

          {showNewConn && (
            <div className="card mb-2" style={{ padding: '1rem' }}>
              <h3 className="mb-2">New Connection</h3>
              <div className="grid grid-2">
                <div className="form-group">
                  <label>From</label>
                  <select value={connFrom} onChange={e => setConnFrom(e.target.value)}>
                    <option value="">— Select —</option>
                    {locations.map(l => <option key={l.locationId || l.id} value={l.locationId || l.id}>{l.name}</option>)}
                  </select>
                </div>
                <div className="form-group">
                  <label>To</label>
                  <select value={connTo} onChange={e => setConnTo(e.target.value)}>
                    <option value="">— Select —</option>
                    {locations.map(l => <option key={l.locationId || l.id} value={l.locationId || l.id}>{l.name}</option>)}
                  </select>
                </div>
                <div className="form-group"><label>Travel (min)</label><input type="number" value={connMinutes} onChange={e => setConnMinutes(e.target.value)} /></div>
                <div className="form-group"><label>Cost</label><input type="number" value={connCost} onChange={e => setConnCost(e.target.value)} /></div>
              </div>
              <div className="flex gap-2 mt-2">
                <label className="text-sm"><input type="checkbox" checked={connCooled} onChange={e => setConnCooled(e.target.checked)} /> Cooled</label>
              </div>
              <div className="flex gap-1 mt-2">
                <button className="btn btn-primary" onClick={handleCreateConn}>Create</button>
                <button className="btn" onClick={() => setShowNewConn(false)}>Cancel</button>
              </div>
            </div>
          )}

          <div style={{ maxHeight: '500px', overflow: 'auto' }}>
            <table className="table">
              <thead>
                <tr><th>From</th><th>To</th><th>Time</th><th>Cost</th><th>Cooled</th><th>Active</th><th></th></tr>
              </thead>
              <tbody>
                {connections.map((conn) => (
                  <tr key={conn.connectionId || conn.id}>
                    <td className="text-sm">{conn.fromLocationId?.slice(0, 8)}...</td>
                    <td className="text-sm">{conn.toLocationId?.slice(0, 8)}...</td>
                    <td>{conn.travelMinutes}m</td>
                    <td>{conn.costUnits}</td>
                    <td>{conn.cooled ? '✓' : '—'}</td>
                    <td>
                      <button
                        className={`btn btn-sm ${conn.active ? 'btn-primary' : 'btn-danger'}`}
