        </button>
        <button className={`btn btn-sm ${tab === 'connections' ? 'btn-primary' : ''}`} onClick={() => setTab('connections')}>
          Connections ({connections.length})
        </button>
      </div>

      {tab === 'locations' && (
        <>
          <div className="flex-between mb-2">
            <span></span>
            <button className="btn btn-primary btn-sm" onClick={() => setShowNewLoc(true)}>Add Location</button>
          </div>

          {showNewLoc && (
            <div className="card mb-2" style={{ padding: '1rem' }}>
              <h3 className="mb-2">New Location</h3>
              <div className="grid grid-3">
                <div className="form-group"><label>Name</label><input value={locName} onChange={e => setLocName(e.target.value)} /></div>
                <div className="form-group"><label>Latitude</label><input type="number" step="any" value={locLat} onChange={e => setLocLat(e.target.value)} /></div>
                <div className="form-group"><label>Longitude</label><input type="number" step="any" value={locLng} onChange={e => setLocLng(e.target.value)} /></div>
                <div className="form-group"><label>Coverage (km)</label><input type="number" step="any" value={locCov} onChange={e => setLocCov(e.target.value)} /></div>
                <div className="form-group"><label>Handling (min)</label><input type="number" step="any" value={locHand} onChange={e => setLocHand(e.target.value)} /></div>
              </div>
              <div className="flex gap-2 mt-2">
                <label className="text-sm"><input type="checkbox" checked={locCollection} onChange={e => setLocCollection(e.target.checked)} /> Collection</label>
                <label className="text-sm"><input type="checkbox" checked={locTransfer} onChange={e => setLocTransfer(e.target.checked)} /> Transfer/Hub</label>
                <label className="text-sm"><input type="checkbox" checked={locLab} onChange={e => setLocLab(e.target.checked)} /> Laboratory</label>
              </div>
              <div className="flex gap-1 mt-2">
                <button className="btn btn-primary" onClick={handleCreateLoc}>Create</button>
                <button className="btn" onClick={() => setShowNewLoc(false)}>Cancel</button>
