                    <td>
                      <button className={`btn btn-sm ${loc.active ? 'btn-primary' : 'btn-danger'}`} onClick={() => handleToggleLoc(loc.locationId!, loc.active)}>
                        {loc.active ? 'Active' : 'Inactive'}
                      </button>
                    </td>
                    <td>
                      <button className={`btn btn-sm ${loc.functions?.collection ? 'btn-primary' : ''}`} onClick={() => handleToggleFunc(loc.locationId!, 'collection', loc.functions?.collection)}>
                        {loc.functions?.collection ? 'On' : 'Off'}
                      </button>
                    </td>
                    <td>
                      <button className={`btn btn-sm ${loc.functions?.transfer ? 'btn-primary' : ''}`} onClick={() => handleToggleFunc(loc.locationId!, 'transfer', loc.functions?.transfer)}>
                        {loc.functions?.transfer ? 'On' : 'Off'}
                      </button>
                    </td>
                    <td>
                      <button className={`btn btn-sm ${loc.functions?.laboratory ? 'btn-primary' : ''}`} onClick={() => handleToggleFunc(loc.locationId!, 'laboratory', loc.functions?.laboratory)}>
                        {loc.functions?.laboratory ? 'On' : 'Off'}
                      </button>
                    </td>
                    <td className="text-sm">
                      {loc.capacity ? `${loc.capacity.capacityUnits || 0}u` : '—'}
                    </td>
                    <td>
                      <button className="btn btn-sm" onClick={() => handleCapConfig(loc.locationId!)}>Capacity</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </>
      )}

      {tab === 'connections' && (
        <>
          <div className="flex-between mb-2">
            <span></span>
            <button className="btn btn-primary btn-sm" onClick={() => setShowNewConn(true)}>Add Connection</button>
          </div>

          {showNewConn && (
            <div className="card mb-2" style={{ padding: '1rem' }}>
              <h3 className="mb-2">New Connection</h3>
              <div className="grid grid-2">
                <div className="form-group">
                  <label>From</label>
                  <select value={connFrom} onChange={e => setConnFrom(e.target.value)}>
                    <option value="">— Select —</option>
                    {locations.map(l => <option key={l.locationId || l.id} value={l.locationId || l.id}>{l.name}</option>)}
                  </select>
                </div>
                <div className="form-group">
                  <label>To</label>
                  <select value={connTo} onChange={e => setConnTo(e.target.value)}>
                    <option value="">— Select —</option>
                    {locations.map(l => <option key={l.locationId || l.id} value={l.locationId || l.id}>{l.name}</option>)}
                  </select>
                </div>
                <div className="form-group"><label>Travel (min)</label><input type="number" value={connMinutes} onChange={e => setConnMinutes(e.target.value)} /></div>
