                <button className="btn" onClick={() => setShowNewLoc(false)}>Cancel</button>
              </div>
            </div>
          )}

          <div style={{ maxHeight: '500px', overflow: 'auto' }}>
            <table className="table">
              <thead>
                <tr><th>Name</th><th>Coordinate</th><th>Active</th><th>Collection</th><th>Transfer</th><th>Lab</th><th>Capacity</th><th></th></tr>
              </thead>
              <tbody>
                {locations.map((loc) => (
                  <tr key={loc.locationId}>
                    <td className="font-bold">{loc.name}</td>
                    <td className="text-sm">{loc.coordinate?.latitude?.toFixed(3)}, {loc.coordinate?.longitude?.toFixed(3)}</td>
                    <td>
                      <button className={`btn btn-sm ${loc.active ? 'btn-primary' : 'btn-danger'}`} onClick={() => handleToggleLoc(loc.locationId!, loc.active)}>
                        {loc.active ? 'Active' : 'Inactive'}
                      </button>
                    </td>
                    <td>
                      <button className={`btn btn-sm ${loc.functions?.collection ? 'btn-primary' : ''}`} onClick={() => handleToggleFunc(loc.locationId!, 'collection', loc.functions?.collection ?? false)}>
                        {loc.functions?.collection ? 'On' : 'Off'}
                      </button>
                    </td>
                    <td>
                      <button className={`btn btn-sm ${loc.functions?.transfer ? 'btn-primary' : ''}`} onClick={() => handleToggleFunc(loc.locationId!, 'transfer', loc.functions?.transfer ?? false)}>
                        {loc.functions?.transfer ? 'On' : 'Off'}
                      </button>
                    </td>
