                <label className="text-sm"><input type="checkbox" checked={locTransfer} onChange={e => setLocTransfer(e.target.checked)} /> Transfer/Hub</label>
                <label className="text-sm"><input type="checkbox" checked={locLab} onChange={e => setLocLab(e.target.checked)} /> Laboratory</label>
