with open('contracts/openapi.contract.json') as f:
    c = json.load(f)

contract_paths = set()
for p, methods in c['paths'].items():
    for m in methods:
        contract_paths.add((m.upper(), p))

# Parse backend routes
import subprocess
res = subprocess.run(['grep', '-rn', 'mux.HandleFunc\|mux.Handle(', '/workspace/backend/main.go'], capture_output=True, text=True)
lines = res.stdout.strip().split('\n')
backend_paths = set()
for line in lines:
    line = line.strip()
    if 'mux.HandleFunc' in line:
        parts = line.split('"')
        if len(parts) >= 3:
            route = parts[1]
            method, path = route.split(' ', 1)
            backend_paths.add((method, path))
    elif 'mux.Handle(' in line:
        parts = line.split('"')
        if len(parts) >= 3:
            path = parts[1]
            backend_paths.add(('*', path))

# Compare
contract_only = contract_paths - backend_paths
backend_only = {p for p in backend_paths if p[0] not in ('*','OPTIONS') and not any(p[1] == cp[1] for cp in contract_paths)}

for p in sorted(contract_paths):
    if p[1].startswith('/ready') or p[1] == '/api/events':
        continue
    bp = (p[0], p[1].replace('/api/', '/api/'))
    if p not in backend_paths:
        print(f'CONTRACT ONLY: {p}')
print()
print('BACKEND ROUTES:')
for p in sorted(backend_paths):
    print(f'  {p[0]:7} {p[1]}')
""}

