import json

with open('/workspace/contracts/openapi.contract.json') as f:
    c = json.load(f)

contract_paths = {}
for p, methods in c['paths'].items():
    for m in methods:
        contract_paths[p] = m.upper()

# Read backend routes from main.go
with open('/workspace/backend/main.go') as f:
    content = f.read()

import re
backend_routes = {}
for match in re.finditer(r'mux\.HandleFunc\("([A-Z]+) (/[^"]+)"', content):
    method, path = match.groups()
    backend_routes[path] = method

# Compare
for path, method in sorted(contract_paths.items()):
    backend_method = backend_routes.get(path)
    if backend_method is None:
        print(f"MISSING from backend: {method} {path}")
    elif backend_method != method:
        print(f"METHOD mismatch: contract={method} backend={backend_method} for {path}")
    else:
        print(f"OK: {method} {path}")

print("\nExtra backend routes not in contract:")
for path, method in sorted(backend_routes.items()):
    if path not in contract_paths and path not in ('/ready', '/', '/api/events'):
        print(f"  {method} {path}")
