import json, re

with open('/workspace/contracts/openapi.contract.json') as f:
    c = json.load(f)

contract_paths = {}
for p, methods in c['paths'].items():
    for m in methods:
        contract_paths[p] = m.upper()

with open('/workspace/backend/main.go') as f:
    content = f.read()

backend_routes = {}
# Match: mux.Handle("METHOD /path", ...
for match in re.finditer(r'mux\.Handle\("([A-Z]+) (/[^"]+)"', content):
