#!/bin/bash
# Integration tests for Lab Sample Pickup & Delivery System

BASE="http://127.0.0.1:8080"
PASS=0
FAIL=0

log_pass() { PASS=$((PASS+1)); echo "  PASS: $1"; }
log_fail() { FAIL=$((FAIL+1)); echo "  FAIL: $1"; }

assert_status() {
  local actual="$1" expected="$2" label="$3"
  if [ "$actual" = "$expected" ]; then
    log_pass "$label (status=$actual)"
    return 0
  else
    log_fail "$label (expected=$expected got=$actual)"
    return 1
  fi
}

assert_json_ok() {
  local json="$1" label="$2"
  local err=$(echo "$json" | python3 -c "import sys,json; d=json.load(sys.stdin); sys.exit(0 if 'error' not in d else 1)" 2>/dev/null && echo "ok" || echo "error")
  if [ "$err" = "ok" ]; then
    log_pass "$label"
    return 0
  else
    log_fail "$label (got error response: $json)"
    return 1
  fi
}

extract_json() {
  python3 -c "import sys,json; d=json.load(sys.stdin); keys='$1'.split('.'); r=d
for k in keys:
  if isinstance(r, dict): r=r.get(k,'')
  elif isinstance(r, list) and k.isdigit(): r=r[int(k)] if int(k)<len(r) else ''
print(r)" 2>/dev/null
}

