// ============================== SERVICEABILITY ==============================

func (h *Handler) CheckServiceability(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Origin               models.Coordinate `json:"origin"`
		OriginType           string            `json:"originType"`
		OriginNodeID         string            `json:"originNodeId"`
		SampleTypeID         string            `json:"sampleTypeId"`
		RequestedAt          string            `json:"requestedAt"`
		DeliveryDeadline     string            `json:"deliveryDeadline"`
		EarliestCollectionAt string            `json:"earliestCollectionAt"`
		LatestCollectionAt   string            `json:"latestCollectionAt"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "invalid_json", "invalid json")
		return
	}

	result := h.computeServiceability(r.Context(), req.Origin, req.OriginType, req.SampleTypeID)
	h.emitEvent(r.Context(), "serviceability.checked", "serviceability", "", map[string]interface{}{"serviceable": result.Serviceable})

	middleware.WriteJSON(w, 200, map[string]interface{}{"data": result})
}

func (h *Handler) computeServiceability(ctx context.Context, origin models.Coordinate, originType, sampleTypeID string) models.ServiceabilityResult {
	// Get current serviceability version
	var version int
	h.store.PG().QueryRowContext(ctx, "SELECT COALESCE(MAX(version), 0) FROM serviceability_versions").Scan(&version)
	version++

	// Find active collection points within 5km
	rows, err := h.store.PG().QueryContext(ctx,
		`SELECT location_id, name, latitude, longitude, coverage_km FROM locations WHERE active=true AND functions->>'collection_point' = 'true'`)
	if err != nil {
		return models.ServiceabilityResult{Serviceable: false, Reason: "no_active_collection_points", ServiceabilityVersion: version}
	}
	defer rows.Close()

	nearby := false
	var nearestLabID string
	minDist := math.MaxFloat64

	for rows.Next() {
		var lid, name string
		var lat, lng, cov float64
		rows.Scan(&lid, &name, &lat, &lng, &cov)
		dist := haversine(origin.Latitude, origin.Longitude, lat, lng)
		if dist <= cov {
			nearby = true
		}
	}

	if !nearby && originType == "home" {
		return models.ServiceabilityResult{Serviceable: false, Reason: "origin_outside_coverage", ServiceabilityVersion: version}
	}

	// For node/clinic origins, check if origin is at a known active node
	if originType == "node" || originType == "clinic" {
		nearby = true // Assume the origin node is known and active
	}

	// Find accepting laboratories
	labRows, err := h.store.PG().QueryContext(ctx,
		`SELECT l.location_id, l.latitude, l.longitude
		 FROM locations l
		 JOIN laboratory_acceptances la ON l.location_id = la.laboratory_id
		 WHERE l.active=true AND l.functions->>'laboratory' = 'true' AND la.sample_type_id=$1 AND la.accepts=true`, sampleTypeID)
	if err != nil {
		return models.ServiceabilityResult{Serviceable: false, Reason: "no_accepting_laboratory", ServiceabilityVersion: version}
	}
	defer labRows.Close()

	for labRows.Next() {
		var labID string
		var labLat, labLng float64
		labRows.Scan(&labID, &labLat, &labLng)
		dist := haversine(origin.Latitude, origin.Longitude, labLat, labLng)
		if dist < minDist {
			minDist = dist
			nearestLabID = labID
		}
	}

	if nearestLabID == "" {
		return models.ServiceabilityResult{Serviceable: false, Reason: "no_accepting_laboratory", ServiceabilityVersion: version}
	}

	// Check route existence (simplified: any connection from any collection point to lab counts)
	var routeExists bool
	h.store.PG().QueryRowContext(ctx,
		`SELECT EXISTS(
			SELECT 1 FROM connections c
			JOIN locations l1 ON c.from_location_id = l1.location_id
			JOIN locations l2 ON c.to_location_id = l2.location_id
			WHERE l1.functions->>'collection_point' = 'true'
			AND l2.location_id = $1
			AND c.active = true
		)`, nearestLabID).Scan(&routeExists)

	if !routeExists {
		return models.ServiceabilityResult{Serviceable: false, Reason: "no_valid_route", ServiceabilityVersion: version}
	}

	estArrival := time.Now().Add(2 * time.Hour)
	return models.ServiceabilityResult{
		Serviceable:          true,
		Reason:               "route_available",
		TargetLaboratoryID:   nearestLabID,
		EstimatedArrivalAt:   &estArrival,
		ServiceabilityVersion: version,
	}
}

func (h *Handler) ReadServiceabilitySnapshot(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
