func (h *Handler) buildOperationsState(ctx context.Context) *models.OperationsState {
	state := &models.OperationsState{
		Samples:                   []map[string]interface{}{},
		Workers:                   []map[string]interface{}{},
		Locations:                 []models.OperationsLocation{},
		Connections:               []models.OperationsConnection{},
		Routes:                    []map[string]interface{}{},
		Handoffs:                  []map[string]interface{}{},
		Delays:                    []map[string]interface{}{},
		Exceptions:                []map[string]interface{}{},
		AssignmentCountSpread:     0,
		IneligibleAssignmentCount: 0,
	}

	// Samples
	sampleRows, _ := h.store.PG().QueryContext(ctx,
		`SELECT sample_id, request_id, status, origin_lat, origin_lng, delivery_deadline, current_holder_id, active_journey_id, latest_lat, latest_lng, location_recorded_at
		 FROM samples WHERE status != 'received' AND status != 'cancelled' ORDER BY created_at DESC LIMIT 200`)
	if sampleRows != nil {
		defer sampleRows.Close()
		for sampleRows.Next() {
			var sid, rid, status, curHolder, activeJourney string
			var originLat, originLng float64
			var deadline time.Time
			var latestLat, latestLng *float64
			var locRecAt *time.Time
			sampleRows.Scan(&sid, &rid, &status, &originLat, &originLng, &deadline, &curHolder, &activeJourney, &latestLat, &latestLng, &locRecAt)
			entry := map[string]interface{}{
				"sampleId":         sid,
				"status":           status,
				"requestId":        rid,
				"origin":           models.Coordinate{Latitude: originLat, Longitude: originLng},
				"deliveryDeadline": deadline,
				"currentHolderId":  curHolder,
				"activeJourneyId":  activeJourney,
				"locationStale":    h.isLocationStale(locRecAt),
			}
			if latestLat != nil && latestLng != nil {
				entry["latestLocation"] = models.Coordinate{Latitude: *latestLat, Longitude: *latestLng}
			}
			if locRecAt != nil {
				entry["locationRecordedAt"] = locRecAt
			}
			state.Samples = append(state.Samples, entry)
		}
	}

	// Workers
	workerRows, _ := h.store.PG().QueryContext(ctx,
		`SELECT user_id, full_name, roles, available, capacity_units, current_lat, current_lng, location_recorded_at
		 FROM users WHERE active=true ORDER BY full_name`)
	if workerRows != nil {
		defer workerRows.Close()
		for workerRows.Next() {
			var wid, name string
			var rolesJSON []byte
			var available bool
			var capUnits int
			var lat, lng *float64
			var locRecAt *time.Time
			workerRows.Scan(&wid, &name, &rolesJSON, &available, &capUnits, &lat, &lng, &locRecAt)
			var roles []string
			json.Unmarshal(rolesJSON, &roles)

			// Count assignments
			var assignCount int
			h.store.PG().QueryRowContext(ctx, "SELECT COUNT(*) FROM assignments WHERE worker_id=$1 AND status IN ('accepted','in_progress')", wid).Scan(&assignCount)

			entry := map[string]interface{}{
				"workerId":        wid,
				"fullName":        name,
				"roles":           roles,
				"available":       available,
				"status":          map[bool]string{true: "available", false: "unavailable"}[available],
				"capacityUnits":   capUnits,
				"assignmentCount": assignCount,
				"locationStale":   h.isLocationStale(locRecAt),
			}
			if lat != nil && lng != nil {
				entry["latestLocation"] = models.Coordinate{Latitude: *lat, Longitude: *lng}
				entry["latest_location"] = models.Coordinate{Latitude: *lat, Longitude: *lng}
			}
			if locRecAt != nil {
				entry["locationRecordedAt"] = locRecAt
			}
			state.Workers = append(state.Workers, entry)
		}
	}

	// Locations
	locRows, _ := h.store.PG().QueryContext(ctx,
		`SELECT l.location_id, l.name, l.latitude, l.longitude, l.active, l.coverage_km, l.handling_minutes, l.functions,
		 COALESCE(lc.capacity_units, 0), COALESCE(lc.reserved_units, 0), COALESCE(lc.cooled_capacity_units, 0), COALESCE(lc.cooled_reserved_units, 0)
		 FROM locations l LEFT JOIN location_capacity lc ON l.location_id=lc.location_id ORDER BY l.name`)
	if locRows != nil {
		defer locRows.Close()
		for locRows.Next() {
			var ol models.OperationsLocation
			var funcJSON []byte
			var capUnits, resUnits, cooledCap, cooledRes int
			locRows.Scan(&ol.LocationID, &ol.Name, &ol.Coordinate.Latitude, &ol.Coordinate.Longitude, &ol.Active, &ol.CoverageKm, &ol.HandlingMinutes, &funcJSON, &capUnits, &resUnits, &cooledCap, &cooledRes)
			json.Unmarshal(funcJSON, &ol.Functions)
			ol.ID = ol.LocationID
			ol.Capacity = &models.Capacity{
				CapacityUnits:       capUnits,
				ReservedUnits:       resUnits,
				AvailableUnits:      capUnits - resUnits,
				CooledCapacityUnits: cooledCap,
				CooledReservedUnits: cooledRes,
				CooledAvailableUnits: cooledCap - cooledRes,
			}
			if !ol.Functions.Laboratory {
				ol.Capacity = nil
			}
			state.Locations = append(state.Locations, ol)
		}
	}

	// Connections
	connRows, _ := h.store.PG().QueryContext(ctx,
		`SELECT c.connection_id, c.from_location_id, c.to_location_id, c.travel_minutes, c.cost_units, c.cooled, c.active,
		 COALESCE(cc.capacity_units, 0), COALESCE(cc.reserved_units, 0), COALESCE(cc.cooled_capacity_units, 0), COALESCE(cc.cooled_reserved_units, 0)
		 FROM connections c LEFT JOIN connection_capacity cc ON c.connection_id=cc.connection_id ORDER BY c.travel_minutes`)
	if connRows != nil {
		defer connRows.Close()
		for connRows.Next() {
			var oc models.OperationsConnection
			var capUnits, resUnits, cooledCap, cooledRes int
			connRows.Scan(&oc.ConnectionID, &oc.FromLocationID, &oc.ToLocationID, &oc.TravelMinutes, &oc.CostUnits, &oc.Cooled, &oc.Active, &capUnits, &resUnits, &cooledCap, &cooledRes)
			oc.ID = oc.ConnectionID
			oc.Capacity = &models.Capacity{
				CapacityUnits:      capUnits,
				ReservedUnits:      resUnits,
				AvailableUnits:     capUnits - resUnits,
				CooledCapacityUnits: cooledCap,
				CooledReservedUnits: cooledRes,
				CooledAvailableUnits: cooledCap - cooledRes,
			}
			state.Connections = append(state.Connections, oc)
		}
	}

	// Handoffs
	handoffRows, _ := h.store.PG().QueryContext(ctx, "SELECT handoff_id, sample_id, from_worker_id, to_worker_id, status, sender_confirmed, receiver_confirmed FROM handoffs WHERE status != 'completed' LIMIT 100")
	if handoffRows != nil {
		defer handoffRows.Close()
		for handoffRows.Next() {
			var h struct {
				HandoffID, SampleID, FromWorker, ToWorker, Status string
				SenderConfirmed, ReceiverConfirmed               bool
			}
			handoffRows.Scan(&h.HandoffID, &h.SampleID, &h.FromWorker, &h.ToWorker, &h.Status, &h.SenderConfirmed, &h.ReceiverConfirmed)
			state.Handoffs = append(state.Handoffs, map[string]interface{}{
				"handoffId":         h.HandoffID,
				"sampleId":          h.SampleID,
				"fromWorkerId":      h.FromWorker,
				"toWorkerId":        h.ToWorker,
				"status":            h.Status,
				"senderConfirmed":   h.SenderConfirmed,
				"receiverConfirmed": h.ReceiverConfirmed,
			})
		}
	}

	// Compute assignment spread
	var counts []int
	assignRows, _ := h.store.PG().QueryContext(ctx, "SELECT COUNT(*) FROM assignments WHERE status IN ('accepted','in_progress') GROUP BY worker_id")
	if assignRows != nil {
		defer assignRows.Close()
		for assignRows.Next() {
			var c int
			assignRows.Scan(&c)
			counts = append(counts, c)
		}
	}
	if len(counts) > 1 {
		min, max := counts[0], counts[0]
		for _, c := range counts {
			if c < min {
				min = c
			}
			if c > max {
				max = c
			}
		}
		state.AssignmentCountSpread = max - min
	}

	return state
}

// ============================== AUDIT ==============================

func (h *Handler) SearchAuditTrail(w http.ResponseWriter, r *http.Request) {
	if !middleware.HasRole(r, "dispatcher") && !middleware.HasRole(r, "administrator") {
		middleware.WriteError(w, 403, "forbidden", "forbidden")
		return
	}

	var req struct {
		Query      string `json:"query"`
		ActorID    string `json:"actorId"`
		EntityType string `json:"entityType"`
		EntityID   string `json:"entityId"`
		Action     string `json:"action"`
		Role       string `json:"role"`
		Success    *bool  `json:"success"`
		FromTime   string `json:"fromTime"`
		ToTime     string `json:"toTime"`
		Limit      int    `json:"limit"`
		Offset     int    `json:"offset"`
		Order      string `json:"order"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "invalid_json", "invalid json")
		return
	}

	if req.Limit <= 0 {
		req.Limit = 50
	}
	if req.Limit > 200 {
		middleware.WriteError(w, 400, "invalid_limit", "invalid limit")
		return
	}
	if req.Order == "" {
		req.Order = "newest_first"
	}
	if req.Order != "newest_first" && req.Order != "oldest_first" {
		middleware.WriteError(w, 400, "invalid_order", "invalid order")
		return
	}

	ctx := r.Context()
	filter := bson.M{}

	if req.ActorID != "" {
		filter["actor_id"] = req.ActorID
	}
	if req.EntityType != "" {
		filter["entity_type"] = req.EntityType
	}
	if req.EntityID != "" {
		filter["entity_id"] = req.EntityID
	}
	if req.Action != "" {
		filter["action"] = req.Action
	}
	if req.Role != "" {
		filter["actor_role"] = req.Role
	}
	if req.Success != nil {
		filter["success"] = *req.Success
	}
	if req.FromTime != "" {
		t, _ := time.Parse(time.RFC3339, req.FromTime)
		filter["occurred_at"] = bson.M{"$gte": t}
	}
	if req.ToTime != "" {
		t, _ := time.Parse(time.RFC3339, req.ToTime)
		if existing, ok := filter["occurred_at"].(bson.M); ok {
			existing["$lte"] = t
		} else {
			filter["occurred_at"] = bson.M{"$lte": t}
		}
	}

	sortOrder := -1
	if req.Order == "oldest_first" {
		sortOrder = 1
	}

	opts := options.Find().SetSort(bson.D{{Key: "occurred_at", Value: sortOrder}}).SetSkip(int64(req.Offset)).SetLimit(int64(req.Limit + 1))
	cursor, err := h.store.Mongo().Collection("audit_logs").Find(ctx, filter, opts)
	if err != nil {
		middleware.WriteError(w, 500, "internal_error", "audit search failed")
		return
	}
	defer cursor.Close(ctx)

	var entries []models.AuditEntry
	cursor.All(ctx, &entries)

	totalCount, _ := h.store.Mongo().Collection("audit_logs").CountDocuments(ctx, filter)

	hasMore := len(entries) > req.Limit
	if hasMore {
		entries = entries[:req.Limit]
	}
	returned := len(entries)

	result := models.AuditSearchResult{
		Entries:  entries,
		Total:    int(totalCount),
		Returned: returned,
		Offset:   req.Offset,
		Limit:    req.Limit,
		Order:    req.Order,
		HasMore:  hasMore,
	}
	if hasMore {
		next := req.Offset + returned
		result.NextOffset = &next
	}

	middleware.WriteJSON(w, 200, map[string]interface{}{"data": result})
}

// ============================== UI BOOTSTRAP ==============================

func (h *Handler) ReadUIBootstrap(w http.ResponseWriter, r *http.Request) {
	uid := middleware.GetUserID(r)
	role := middleware.GetActiveRole(r)
	ctx := r.Context()

	var username, fullName string
	var rolesJSON []byte
	h.store.PG().QueryRowContext(ctx, "SELECT username, full_name, roles FROM users WHERE user_id=$1", uid).Scan(&username, &fullName, &rolesJSON)
	var roles []string
	json.Unmarshal(rolesJSON, &roles)

	user := map[string]interface{}{
		"userId":     uid,
		"username":   username,
		"fullName":   fullName,
		"roles":      roles,
		"activeRole": role,
	}

	response := map[string]interface{}{
		"data": map[string]interface{}{
			"user":       user,
			"serverTime": time.Now(),
		},
	}

	if role == "requester" {
		var reqSamples []map[string]interface{}
		rows, _ := h.store.PG().QueryContext(ctx, "SELECT sample_id, status, serviceability FROM samples WHERE requester_id=$1 ORDER BY created_at DESC LIMIT 100", uid)
		if rows != nil {
			defer rows.Close()
			for rows.Next() {
				var sid, status, svc string
				rows.Scan(&sid, &status, &svc)
				reqSamples = append(reqSamples, map[string]interface{}{
					"sampleId": sid, "status": status, "serviceability": svc,
				})
			}
		}
		response["data"].(map[string]interface{})["requesterSamples"] = reqSamples
	}

	if role == "dispatcher" || role == "administrator" {
		ops := h.buildOperationsState(ctx)
		response["data"].(map[string]interface{})["operations"] = ops
	}

	middleware.WriteJSON(w, 200, response)
}

// ============================== WEBSOCKET ==============================

func (h *Handler) StreamRealtimeEvents(w http.ResponseWriter, r *http.Request) {
	proto := r.Header.Get("Sec-WebSocket-Protocol")
	uid, role, roles, err := middleware.WSSubprotocolAuth(proto)
	if err != nil {
		middleware.WriteError(w, 401, "unauthorized", "ws auth failed")
		return
	}

	sinceStr := r.URL.Query().Get("since")
	var since int64
	if sinceStr != "" {
		since, _ = strconv.ParseInt(sinceStr, 10, 64)
	}

	conn, err := upgrader.Upgrade(w, r, http.Header{"Sec-WebSocket-Protocol": {proto}})
	if err != nil {
		return
	}

	wsc := &wsConn{conn: conn, userID: uid, role: role, roles: roles, since: since}

	// Register connection
	clients, _ := h.wsClients.LoadOrStore(role, &sync.Map{})
	connID := uuid.New().String()
	clients.(*sync.Map).Store(connID, wsc)

	defer func() {
		if cmap, ok := h.wsClients.Load(role); ok {
			cmap.(*sync.Map).Delete(connID)
		}
		conn.Close()
	}()

	// Send replay events if since > 0
	if since > 0 {
		ctx := r.Context()
		cursor, _ := h.store.Mongo().Collection("events").Find(ctx,
			bson.M{"id": bson.M{"$gt": since}},
			options.Find().SetSort(bson.D{{Key: "id", Value: 1}}))
		if cursor != nil {
			var events []models.RealtimeEvent
			cursor.All(ctx, &events)
			for _, evt := range events {
				conn.WriteJSON(evt)
			}
		}
	}

	// Keep alive
	for {
		_, _, err := conn.ReadMessage()
		if err != nil {
			break
		}
	}
}

func (h *Handler) emitEvent(ctx context.Context, eventType, entityType, entityID string, payload map[string]interface{}) {
	seq := h.store.NextEventID(ctx)
	event := models.RealtimeEvent{
		ID:         seq,
		Type:       eventType,
		EntityType: entityType,
		EntityID:   entityID,
		Payload:    payload,
		CreatedAt:  time.Now(),
	}

	// Save to MongoDB
	h.store.Mongo().Collection("events").InsertOne(context.Background(), event)

	// Store latest seq in redis
	h.store.Redis().Set(context.Background(), "event:latest", seq, 0)

	// Broadcast to relevant WebSocket clients
	eventJSON, _ := json.Marshal(event)

	h.wsClients.Range(func(roleKey, clients interface{}) bool {
		cmap := clients.(*sync.Map)
		cmap.Range(func(key, value interface{}) bool {
			wsc := value.(*wsConn)
			if wsc.since < seq {
				wsc.conn.WriteMessage(websocket.TextMessage, eventJSON)
			}
			return true
		})
		return true
	})

	h.store.PersistEventSeq(context.Background())
}

