// ============================== HANDOFF ==============================

func (h *Handler) InitiateHandoff(w http.ResponseWriter, r *http.Request) {
	var req struct {
		SampleID       string `json:"sampleId"`
		ToWorkerID     string `json:"toWorkerId"`
		FromLocationID string `json:"fromLocationId"`
		ToLocationID   string `json:"toLocationId"`
		InitiatedAt    string `json:"initiatedAt"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "invalid_json", "invalid json")
		return
	}

	fromWorkerID := middleware.GetUserID(r)
	ctx := r.Context()
	initiatedAt, _ := time.Parse(time.RFC3339, req.InitiatedAt)
	if initiatedAt.IsZero() {
		initiatedAt = time.Now()
	}

	// Verify current holder
	var currentHolderID string
	h.store.PG().QueryRowContext(ctx, "SELECT current_holder_id FROM samples WHERE sample_id=$1", req.SampleID).Scan(&currentHolderID)
	if currentHolderID != fromWorkerID {
		middleware.WriteError(w, 409, "custody_conflict", "you are not the current holder")
		return
	}

	handoffID := uuid.New().String()
	h.store.PG().ExecContext(ctx,
		`INSERT INTO handoffs (handoff_id, sample_id, from_worker_id, to_worker_id, from_location_id, to_location_id, status, current_holder_id, initiated_at)
		 VALUES ($1,$2,$3,$4,$5,$6,'initiated',$3,$7)`,
		handoffID, req.SampleID, fromWorkerID, req.ToWorkerID, nullUUID(req.FromLocationID), nullUUID(req.ToLocationID), initiatedAt)

	h.store.PG().ExecContext(ctx, "UPDATE samples SET pending_handoff_id=$1 WHERE sample_id=$2", handoffID, req.SampleID)

	middleware.WriteJSON(w, 201, map[string]interface{}{
		"data": map[string]interface{}{
			"handoffId":      handoffID,
			"status":         "initiated",
			"senderConfirmed":  false,
			"receiverConfirmed": false,
			"currentHolderId": fromWorkerID,
		},
	})
}

func (h *Handler) ConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	var req struct {
		HandoffID        string `json:"handoffId"`
		ConfirmationSide string `json:"confirmationSide"`
		ConfirmedAt      string `json:"confirmedAt"`
		IdempotencyKey   string `json:"idempotencyKey"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "invalid_json", "invalid json")
		return
	}

	uid := middleware.GetUserID(r)
	ctx := r.Context()
	confirmedAt, _ := time.Parse(time.RFC3339, req.ConfirmedAt)
	if confirmedAt.IsZero() {
		confirmedAt = time.Now()
	}

	var fromWorkerID, toWorkerID, status, currentHolderID, sampleID string
	var senderConfirmed, receiverConfirmed bool
	h.store.PG().QueryRowContext(ctx,
		`SELECT from_worker_id, to_worker_id, status, sender_confirmed, receiver_confirmed, current_holder_id, sample_id
		 FROM handoffs WHERE handoff_id=$1`, req.HandoffID).Scan(&fromWorkerID, &toWorkerID, &status, &senderConfirmed, &receiverConfirmed, &currentHolderID, &sampleID)

	if status == "completed" {
		middleware.WriteError(w, 409, "handoff_inactive", "handoff already completed")
		return
	}

	if req.ConfirmationSide == "sender" {
		if uid != fromWorkerID {
			middleware.WriteError(w, 403, "forbidden", "not the sender")
			return
		}
		if senderConfirmed {
			middleware.WriteError(w, 409, "handoff_inactive", "sender already confirmed")
			return
		}
		h.store.PG().ExecContext(ctx, "UPDATE handoffs SET sender_confirmed=true, sender_confirmed_at=$1 WHERE handoff_id=$2", confirmedAt, req.HandoffID)
		senderConfirmed = true
	} else if req.ConfirmationSide == "receiver" {
		if uid != toWorkerID {
			middleware.WriteError(w, 403, "forbidden", "not the receiver")
			return
		}
		if receiverConfirmed {
			middleware.WriteError(w, 409, "handoff_inactive", "receiver already confirmed")
			return
		}
		h.store.PG().ExecContext(ctx, "UPDATE handoffs SET receiver_confirmed=true, receiver_confirmed_at=$1 WHERE handoff_id=$2", confirmedAt, req.HandoffID)
		receiverConfirmed = true
	} else {
		middleware.WriteError(w, 400, "invalid_confirmation_side", "invalid side")
		return
	}

	newHolder := currentHolderID
	if senderConfirmed && receiverConfirmed {
		newHolder = toWorkerID
		h.store.PG().ExecContext(ctx, "UPDATE handoffs SET status='completed', current_holder_id=$1 WHERE handoff_id=$2", newHolder, req.HandoffID)
		h.store.PG().ExecContext(ctx, "UPDATE samples SET current_holder_id=$1, pending_handoff_id=NULL, updated_at=now() WHERE sample_id=$2", newHolder, sampleID)
		h.addTimeline(ctx, sampleID, "custody_transfer", uid, middleware.GetActiveRole(r), true, map[string]interface{}{"new_holder": newHolder})
	}

	middleware.WriteJSON(w, 201, map[string]interface{}{
		"data": map[string]interface{}{
			"handoffId":          req.HandoffID,
			"status":             "completed",
			"senderConfirmed":    senderConfirmed,
			"receiverConfirmed":  receiverConfirmed,
			"currentHolderId":    newHolder,
		},
	})
}

// ============================== LABORATORY RECEIPT ==============================

func (h *Handler) ConfirmLaboratoryReceipt(w http.ResponseWriter, r *http.Request) {
	if !middleware.HasRole(r, "laboratory_team") {
		middleware.WriteError(w, 403, "forbidden", "forbidden")
		return
	}

	var req struct {
		SampleID      string `json:"sampleId"`
		LaboratoryID  string `json:"laboratoryId"`
		ReceivedAt    string `json:"receivedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "invalid_json", "invalid json")
		return
	}

	uid := middleware.GetUserID(r)
	ctx := r.Context()
	receivedAt, _ := time.Parse(time.RFC3339, req.ReceivedAt)
	if receivedAt.IsZero() {
		receivedAt = time.Now()
	}

	// Check pending handoff
	var pendingHandoff string
	h.store.PG().QueryRowContext(ctx, "SELECT COALESCE(pending_handoff_id::text, '') FROM samples WHERE sample_id=$1", req.SampleID).Scan(&pendingHandoff)
	if pendingHandoff != "" {
		middleware.WriteError(w, 409, "pending_handoff_exists", "pending handoff exists")
		return
	}

	// Check delivery deadline
	var deadline time.Time
	h.store.PG().QueryRowContext(ctx, "SELECT delivery_deadline FROM samples WHERE sample_id=$1", req.SampleID).Scan(&deadline)
	if receivedAt.After(deadline) {
		middleware.WriteError(w, 409, "delivery_deadline_exceeded", "delivery deadline exceeded")
		return
	}

	h.store.PG().ExecContext(ctx,
		"UPDATE samples SET status='received', received_laboratory_id=$1, updated_at=now() WHERE sample_id=$2",
		req.LaboratoryID, req.SampleID)

	// Complete lab assignment
	h.store.PG().ExecContext(ctx, "UPDATE assignments SET status='completed' WHERE sample_id=$1 AND kind='laboratory'", req.SampleID)
	h.store.PG().ExecContext(ctx, "UPDATE journeys SET status='completed' WHERE journey_id=(SELECT active_journey_id FROM samples WHERE sample_id=$1)", req.SampleID)

	h.addTimeline(ctx, req.SampleID, "laboratory_receipt", uid, middleware.GetActiveRole(r), true, map[string]interface{}{"laboratoryId": req.LaboratoryID})
	h.logAudit(ctx, uid, middleware.GetActiveRole(r), "confirm_laboratory_receipt", "sample", req.SampleID, true, nil)

	middleware.WriteJSON(w, 201, map[string]interface{}{
		"data": map[string]interface{}{
			"sampleId":     req.SampleID,
			"laboratoryId": req.LaboratoryID,
			"status":       "received",
			"receivedAt":   receivedAt,
		},
	})
}

