		req.SampleTypeID, req.ContainerType, req.TemperatureMinC, req.TemperatureMaxC, incompJSON, svc.TargetLaboratoryID).Scan(&sampleID)
	if err != nil {
		middleware.WriteError(w, 500, "internal_error", fmt.Sprintf("create sample: %v", err))
		return
	}

	// Create journey and assignments
	journeyID := uuid.New().String()
