	// Update sample with journey
	h.store.PG().ExecContext(ctx, "UPDATE samples SET active_journey_id=$1 WHERE sample_id=$2", journeyID, sampleID)

	h.logAudit(ctx, requesterID, middleware.GetActiveRole(r), "create_collection_request", "sample", sampleID, true, nil)
