func (h *Handler) logAudit(ctx context.Context, actorID, role, action, entityType, entityID string, success bool, details map[string]interface{}) {
	entry := models.AuditEntry{
		AuditID:    uuid.New().String(),
		ActorID:    actorID,
		Role:       role,
		ActorRole:  role,
		Action:     action,
		EntityType: entityType,
		EntityID:   entityID,
		Success:    success,
		OccurredAt: time.Now(),
		Details:    details,
	}
	if details == nil {
		entry.Details = map[string]interface{}{}
	}
	h.store.Mongo().Collection("audit_logs").InsertOne(context.Background(), entry)
}

func (h *Handler) addTimeline(ctx context.Context, sampleID, action, actorID, role string, success bool, details map[string]interface{}) {
	if details == nil {
		details = map[string]interface{}{}
	}
	var maxID int
	h.store.Mongo().Collection("timeline_events").FindOne(ctx,
		bson.M{"sample_id": sampleID},
		options.FindOne().SetSort(bson.D{{Key: "event_id", Value: -1}})).Decode(&struct{ EventID int `bson:"event_id"` }{})
	maxID++
	entry := bson.M{
		"sample_id": sampleID, "event_id": maxID,
		"action": action, "actor_id": actorID, "role": role,
		"entity_type": "sample", "entity_id": sampleID,
		"success": success, "occurred_at": time.Now(), "details": details,
	}
	h.store.Mongo().Collection("timeline_events").InsertOne(context.Background(), entry)
}

func (h *Handler) getTimeline(ctx context.Context, sampleID string) []models.TimelineEntry {
	var entries []models.TimelineEntry
	filter := bson.M{}
	if sampleID != "" {
		filter["sample_id"] = sampleID
	}
	cursor, _ := h.store.Mongo().Collection("timeline_events").Find(ctx, filter, options.Find().SetSort(bson.D{{Key: "event_id", Value: 1}}))
	if cursor != nil {
		cursor.All(ctx, &entries)
	}
	if entries == nil {
		entries = []models.TimelineEntry{}
	}
	return entries
}

func (h *Handler) isLocationStale(recordedAt *time.Time) bool {
	if recordedAt == nil {
		return true
	}
	return time.Since(*recordedAt) > 30*time.Minute
}

func haversine(lat1, lng1, lat2, lng2 float64) float64 {
	const R = 6371.0
	dLat := (lat2 - lat1) * math.Pi / 180.0
	dLng := (lng2 - lng1) * math.Pi / 180.0
	a := math.Sin(dLat/2)*math.Sin(dLat/2) + math.Cos(lat1*math.Pi/180.0)*math.Cos(lat2*math.Pi/180.0)*math.Sin(dLng/2)*math.Sin(dLng/2)
	return R * 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
}

func nullUUID(s string) interface{} {
	if s == "" {
		return nil
	}
	return s
}

// ensure JWT secret
func init() {
	secret := make([]byte, 32)
	rand.Read(secret)
	middleware.SetJWTSecret(secret)
	log.Printf("JWT secret: %s", base64.StdEncoding.EncodeToString(secret))
	// Also store in a persistent place so restarts work
}

