// ============================== CAPACITY ==============================

func (h *Handler) ConfigureCapacity(w http.ResponseWriter, r *http.Request) {
	role := middleware.GetActiveRole(r)
	if role != "administrator" && role != "node_handler" && role != "laboratory_team" {
		middleware.WriteError(w, 403, "forbidden", "forbidden")
		return
	}

	var req struct {
		ResourceID         string `json:"resourceId"`
		CapacityUnits      int    `json:"capacityUnits"`
		CooledCapacityUnits int   `json:"cooledCapacityUnits"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "invalid_json", "invalid json")
		return
	}
	if req.CapacityUnits < 0 || req.CooledCapacityUnits < 0 {
		middleware.WriteError(w, 400, "invalid_capacity", "invalid capacity")
		return
	}

	ctx := r.Context()
	// Check if it's a location
	var exists bool
	h.store.PG().QueryRowContext(ctx, "SELECT EXISTS(SELECT 1 FROM locations WHERE location_id=$1)", req.ResourceID).Scan(&exists)
	if exists {
		h.store.PG().ExecContext(ctx, `INSERT INTO location_capacity (location_id, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units) VALUES ($3, $1, 0, $2, 0) ON CONFLICT (location_id) DO UPDATE SET capacity_units=$1, cooled_capacity_units=$2`,
			req.CapacityUnits, req.CooledCapacityUnits, req.ResourceID)
	} else {
		h.store.PG().QueryRowContext(ctx, "SELECT EXISTS(SELECT 1 FROM connections WHERE connection_id=$1)", req.ResourceID).Scan(&exists)
		if exists {
			h.store.PG().ExecContext(ctx, `INSERT INTO connection_capacity (connection_id, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units) VALUES ($3, $1, 0, $2, 0) ON CONFLICT (connection_id) DO UPDATE SET capacity_units=$1, cooled_capacity_units=$2`,
				req.CapacityUnits, req.CooledCapacityUnits, req.ResourceID)
		} else {
			middleware.WriteError(w, 404, "not_found", "resource not found")
			return
		}
	}

	middleware.WriteJSON(w, 200, map[string]interface{}{
		"data": map[string]interface{}{
			"resourceId":         req.ResourceID,
			"capacityUnits":      req.CapacityUnits,
			"cooledCapacityUnits": req.CooledCapacityUnits,
		},
	})
}

