func (h *Handler) ReadSampleState(w http.ResponseWriter, r *http.Request) {
	sampleID := r.PathValue("sampleId")
	if sampleID == "" {
		middleware.WriteError(w, 400, "invalid_json", "sampleId required")
		return
	}

	ctx := r.Context()
	var s struct {
		SampleID, RequestID, RequesterID, OriginType, ContainerType, Status, Serviceability, TargetLabID, ActiveJourneyID, SampleTypeID string
		OriginLat, OriginLng, TempMin, TempMax                                                                             float64
		RequestedAt, DeliveryDeadline, LocationRecordedAt                                                                  time.Time
		EarliestAt, LatestAt                                                                                               *time.Time
		OriginNodeID, CurrentHolderID, ActiveJourneyID2                                                                    *string
		IncompJSON, ActiveAssignJSON                                                                                       []byte
		LatestLat, LatestLng                                                                                               *float64
	}
	err := h.store.PG().QueryRowContext(ctx,
		`SELECT sample_id, request_id, requester_id, origin_lat, origin_lng, origin_type, origin_node_id, requested_at, delivery_deadline, earliest_collection_at, latest_collection_at, sample_type_id, container_type, temperature_min_c, temperature_max_c, incompatible_sample_types, status, serviceability, active_journey_id, target_laboratory_id, current_holder_id, latest_lat, latest_lng, location_recorded_at
		 FROM samples WHERE sample_id=$1`, sampleID).Scan(
		&s.SampleID, &s.RequestID, &s.RequesterID, &s.OriginLat, &s.OriginLng, &s.OriginType, &s.OriginNodeID, &s.RequestedAt, &s.DeliveryDeadline, &s.EarliestAt, &s.LatestAt, &s.SampleTypeID, &s.ContainerType, &s.TempMin, &s.TempMax, &s.IncompJSON, &s.Status, &s.Serviceability, &s.ActiveJourneyID, &s.TargetLabID, &s.CurrentHolderID, &s.LatestLat, &s.LatestLng, &s.LocationRecordedAt)
	if err != nil {
		middleware.WriteError(w, 404, "not_found", "sample not found")
		return
	}

	var incompSamples []string
	json.Unmarshal(s.IncompJSON, &incompSamples)

	latestLoc := models.Coordinate{Latitude: s.OriginLat, Longitude: s.OriginLng}
	if s.LatestLat != nil && s.LatestLng != nil {
		latestLoc = models.Coordinate{Latitude: *s.LatestLat, Longitude: *s.LatestLng}
	}

	timeline := h.getTimeline(ctx, sampleID)

	// Get active assignment IDs
	activeAssigns := []string{}
	if s.ActiveJourneyID2 != nil {
		_ = s.ActiveJourneyID2
	}

	// Query assignments for this sample
	assignRows, _ := h.store.PG().QueryContext(ctx, "SELECT assignment_id FROM assignments WHERE sample_id=$1 AND status IN ('offered','accepted','in_progress')", sampleID)
	if assignRows != nil {
		defer assignRows.Close()
		for assignRows.Next() {
			var aid string
			assignRows.Scan(&aid)
			activeAssigns = append(activeAssigns, aid)
		}
	}

	_ = s.IncompJSON
	_ = s.ActiveAssignJSON

	state := models.SampleState{
		SampleID:              s.SampleID,
		RequestID:             s.RequestID,
		RequesterID:           s.RequesterID,
		Origin:                models.Coordinate{Latitude: s.OriginLat, Longitude: s.OriginLng},
		OriginType:            s.OriginType,
		RequestedAt:           s.RequestedAt,
		DeliveryDeadline:      s.DeliveryDeadline,
		SampleTypeID:          s.SampleTypeID,
		ContainerType:         s.ContainerType,
		TemperatureMinC:       s.TempMin,
		TemperatureMaxC:       s.TempMax,
		IncompatibleSampleTypes: incompSamples,
		Serviceability:        s.Serviceability,
		ActiveAssignmentIDs:   activeAssigns,
		State:                 map[string]interface{}{"status": s.Status},
		Timeline:              timeline,
		LatestLocation:        &latestLoc,
		LocationRecordedAt:    &s.LocationRecordedAt,
		LocationStale:         h.isLocationStale(&s.LocationRecordedAt),
	}
	if s.ActiveJourneyID2 != nil {
		state.ActiveJourneyID = *s.ActiveJourneyID2
	}
	if s.TargetLabID != "" {
		state.TargetLaboratoryID = s.TargetLabID
	}
	if s.EarliestAt != nil {
		state.EarliestCollectionAt = s.EarliestAt
	}
	if s.LatestAt != nil {
		state.LatestCollectionAt = s.LatestAt
	}

	middleware.WriteJSON(w, 200, map[string]interface{}{"data": state})
}

func (h *Handler) ReadSampleLifecycle(w http.ResponseWriter, r *http.Request) {
	var req struct {
		SampleID string `json:"sampleId"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "invalid_json", "invalid json")
		return
	}

	ctx := r.Context()
	var sampleID, status, currentHolderID, activeJourneyID, receivedLabID, pendingHandoffID string
	var sealed bool
	var latestLat, latestLng *float64
	var locationRecordedAt *time.Time

	err := h.store.PG().QueryRowContext(ctx,
		`SELECT sample_id, status, sealed, current_holder_id, active_journey_id, received_laboratory_id, pending_handoff_id, latest_lat, latest_lng, location_recorded_at
		 FROM samples WHERE sample_id=$1`, req.SampleID).Scan(&sampleID, &status, &sealed, &currentHolderID, &activeJourneyID, &receivedLabID, &pendingHandoffID, &latestLat, &latestLng, &locationRecordedAt)
	if err != nil {
		middleware.WriteError(w, 404, "not_found", "sample not found")
		return
	}

	timeline := h.getTimeline(ctx, req.SampleID)

	// Get completed leg IDs
	completedLegs := []string{}
	legRows, _ := h.store.PG().QueryContext(ctx, "SELECT assignment_id FROM assignments WHERE sample_id=$1 AND status='completed'", req.SampleID)
	if legRows != nil {
		defer legRows.Close()
		for legRows.Next() {
			var lid string
			legRows.Scan(&lid)
			completedLegs = append(completedLegs, lid)
		}
	}

	// Get active replacement plan IDs
	replacementIDs := []string{}

	lifecycle := map[string]interface{}{
		"sampleId":                sampleID,
		"status":                  status,
		"sealed":                  sealed,
		"completedLegIds":          completedLegs,
		"activeReplacementPlanIds": replacementIDs,
		"timeline":                timeline,
		"activeJourneyId":         activeJourneyID,
		"currentHolderId":         currentHolderID,
		"receivedLaboratoryId":    receivedLabID,
		"pendingHandoffId":        pendingHandoffID,
		"locationStale":           h.isLocationStale(locationRecordedAt),
	}
	if latestLat != nil && latestLng != nil {
		lifecycle["latestLocation"] = models.Coordinate{Latitude: *latestLat, Longitude: *latestLng}
	}
	if locationRecordedAt != nil {
		lifecycle["locationRecordedAt"] = locationRecordedAt
	}

	middleware.WriteJSON(w, 200, map[string]interface{}{"data": lifecycle})
}

