		middleware.WriteError(w, 500, "internal_error", fmt.Sprintf("configure lab acceptance: %v", err))
		return
	}

	middleware.WriteJSON(w, 200, map[string]interface{}{
		"data": map[string]interface{}{
			"acceptanceId": aid,
			"accepts":      req.Accepts,
		},
	})
}

