// ============================== HANDLING CHECKPOINT ==============================

func (h *Handler) RecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	var req struct {
		SampleID             string  `json:"sampleId"`
		AssignmentID         string  `json:"assignmentId"`
		LocationID           string  `json:"locationId"`
		ContainerType        string  `json:"containerType"`
		ObservedTemperatureC float64 `json:"observedTemperatureC"`
		RecordedAt           string  `json:"recordedAt"`
		IdempotencyKey       string  `json:"idempotencyKey"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "invalid_json", "invalid json")
		return
	}

	uid := middleware.GetUserID(r)
	ctx := r.Context()
	recordedAt, _ := time.Parse(time.RFC3339, req.RecordedAt)
	if recordedAt.IsZero() {
		recordedAt = time.Now()
	}

	// Check current holder
	var holderID string
	h.store.PG().QueryRowContext(ctx, "SELECT current_holder_id FROM samples WHERE sample_id=$1", req.SampleID).Scan(&holderID)
	if holderID != uid {
		middleware.WriteError(w, 409, "custody_conflict", "not the current holder")
		return
	}

	h.store.PG().ExecContext(ctx,
		`INSERT INTO handling_checkpoints (sample_id, worker_id, container_type, observed_temperature_c, recorded_at)
		 VALUES ($1,$2,$3,$4,$5)`,
		req.SampleID, uid, req.ContainerType, req.ObservedTemperatureC, recordedAt)

	// Check compliance
	var sampleContainer string
	var tempMin, tempMax float64
	h.store.PG().QueryRowContext(ctx, "SELECT container_type, temperature_min_c, temperature_max_c FROM samples WHERE sample_id=$1", req.SampleID).Scan(&sampleContainer, &tempMin, &tempMax)

	compliant := true
	if req.ObservedTemperatureC < tempMin || req.ObservedTemperatureC > tempMax {
		compliant = false
	}
	if sampleContainer != req.ContainerType {
		compliant = false
	}

	if !compliant {
		exceptionJSON, _ := json.Marshal(map[string]interface{}{
			"reason":                "handling_noncompliant",
			"observedContainerType": req.ContainerType,
			"observedTemperatureC":  req.ObservedTemperatureC,
		})
		h.store.PG().ExecContext(ctx, "UPDATE samples SET status='exception', exception=$1, updated_at=now() WHERE sample_id=$2", exceptionJSON, req.SampleID)
	}

	middleware.WriteJSON(w, 201, map[string]interface{}{
		"data": map[string]interface{}{
			"sampleId":       req.SampleID,
			"status":         "checkpoint_recorded",
			"compliant":      compliant,
			"checkedAt":      recordedAt,
		},
	})
}

// ============================== JOURNEY PLANS ==============================

func (h *Handler) ReadJourneyPlan(w http.ResponseWriter, r *http.Request) {
	var req struct {
		JourneyID string `json:"journeyId"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "invalid_json", "invalid json")
		return
	}

	ctx := r.Context()
	plan := h.loadJourneyPlan(ctx, req.JourneyID)
	if plan == nil {
		middleware.WriteError(w, 404, "not_found", "journey not found")
		return
	}

	uid := middleware.GetUserID(r)
	role := middleware.GetActiveRole(r)

	// Return role-appropriate view
	if role == "requester" {
		reqPlan := models.RequesterJourneyPlan{
			JourneyID:           plan.JourneyID,
			ParentJourneyID:     plan.ParentJourneyID,
			PlanVersion:         plan.PlanVersion,
			RouteMode:           plan.RouteMode,
			Status:              plan.Status,
			EstimatedDeliveryAt: plan.EstimatedDeliveryAt,
			TotalCostUnits:      plan.TotalCostUnits,
			SampleIDs:           plan.SampleIDs,
			OrderedStops:        plan.OrderedStops,
			Legs:                make([]interface{}, len(plan.Legs)),
		}
		for i, l := range plan.Legs {
			reqPlan.Legs[i] = map[string]interface{}{
				"assignmentId": l.AssignmentID, "sequence": l.Sequence, "status": l.Status,
			}
		}
		middleware.WriteJSON(w, 200, map[string]interface{}{"data": reqPlan})
		return
	}

	_ = uid
	middleware.WriteJSON(w, 200, map[string]interface{}{"data": plan})
}

func (h *Handler) loadJourneyPlan(ctx context.Context, journeyID string) *models.JourneyPlan {
	var j models.JourneyPlan
	var stopsJSON, legsJSON, sampleIDsJSON, workerIDsJSON []byte
	var colAssignIDsJSON, nodeAssignIDsJSON, labAssignIDsJSON []byte
	var estDelivery *time.Time

	err := h.store.PG().QueryRowContext(ctx,
		`SELECT journey_id, parent_journey_id, plan_version, route_mode, status, estimated_delivery_at, total_cost_units, capacity_used, capacity_available, sample_ids, ordered_stops, legs, assigned_worker_ids, collection_assignment_id, collection_assignment_ids, node_assignment_ids, laboratory_assignment_ids, first_transport_assignment_id, middle_transport_assignment_id, final_transport_assignment_id, valid, replan_status
		 FROM journeys WHERE journey_id=$1`, journeyID).Scan(
		&j.JourneyID, &j.ParentJourneyID, &j.PlanVersion, &j.RouteMode, &j.Status, &estDelivery, &j.TotalCostUnits, &j.CapacityUsed, &j.CapacityAvailable, &sampleIDsJSON, &stopsJSON, &legsJSON, &workerIDsJSON, &j.CollectionAssignmentID, &colAssignIDsJSON, &nodeAssignIDsJSON, &labAssignIDsJSON, &j.FirstTransportAssignmentID, &j.MiddleTransportAssignmentID, &j.FinalTransportAssignmentID, &j.Valid, &j.ReplanStatus)
	if err != nil {
		return nil
	}
	if estDelivery != nil {
		j.EstimatedDeliveryAt = estDelivery
	}
	json.Unmarshal(sampleIDsJSON, &j.SampleIDs)
	json.Unmarshal(stopsJSON, &j.OrderedStops)
	json.Unmarshal(legsJSON, &j.Legs)
	json.Unmarshal(workerIDsJSON, &j.AssignedWorkerIDs)
	json.Unmarshal(colAssignIDsJSON, &j.CollectionAssignmentIDs)
	json.Unmarshal(nodeAssignIDsJSON, &j.NodeAssignmentIDs)
	json.Unmarshal(labAssignIDsJSON, &j.LaboratoryAssignmentIDs)
	return &j
}

// ============================== JOURNEY MANAGEMENT ==============================

func (h *Handler) CancelJourney(w http.ResponseWriter, r *http.Request) {
	if !middleware.HasRole(r, "dispatcher") && !middleware.HasRole(r, "administrator") {
		middleware.WriteError(w, 403, "forbidden", "forbidden")
		return
	}

	var req struct {
		JourneyID           string `json:"journeyId"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
		Reason              string `json:"reason"`
		IdempotencyKey      string `json:"idempotencyKey"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "invalid_json", "invalid json")
		return
	}

	ctx := r.Context()
	var planVersion int
	var status string
	var sampleIDsJSON []byte
	h.store.PG().QueryRowContext(ctx, "SELECT plan_version, status, sample_ids FROM journeys WHERE journey_id=$1", req.JourneyID).Scan(&planVersion, &status, &sampleIDsJSON)

	if planVersion != req.ExpectedPlanVersion {
		middleware.WriteError(w, 409, "stale_plan", "stale plan version")
		return
	}

	var sampleIDs []string
	json.Unmarshal(sampleIDsJSON, &sampleIDs)

	h.store.PG().ExecContext(ctx, "UPDATE journeys SET status='cancelled', updated_at=now() WHERE journey_id=$1", req.JourneyID)
	h.store.PG().ExecContext(ctx, "UPDATE assignments SET status='cancelled', updated_at=now() WHERE journey_id=$1 AND status IN ('offered','accepted')", req.JourneyID)
	for _, sid := range sampleIDs {
		h.store.PG().ExecContext(ctx, "UPDATE samples SET status='cancelled', updated_at=now() WHERE sample_id=$1", sid)
	}

	h.logAudit(ctx, middleware.GetUserID(r), middleware.GetActiveRole(r), "cancel_journey", "journey", req.JourneyID, true, map[string]interface{}{"reason": req.Reason})

	middleware.WriteJSON(w, 201, map[string]interface{}{
		"data": map[string]interface{}{
			"journeyId": req.JourneyID,
			"status":    "cancelled",
			"sampleIds": sampleIDs,
		},
	})
}

func (h *Handler) EditActivePlan(w http.ResponseWriter, r *http.Request) {
	if !middleware.HasRole(r, "dispatcher") && !middleware.HasRole(r, "administrator") {
		middleware.WriteError(w, 403, "forbidden", "forbidden")
		return
	}

	var req struct {
		JourneyID           string `json:"journeyId"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
		IdempotencyKey      string `json:"idempotencyKey"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "invalid_json", "invalid json")
		return
	}

	ctx := r.Context()
	var planVersion int
	h.store.PG().QueryRowContext(ctx, "SELECT plan_version FROM journeys WHERE journey_id=$1", req.JourneyID).Scan(&planVersion)
	if planVersion != req.ExpectedPlanVersion {
		middleware.WriteError(w, 409, "stale_plan", "stale plan version")
		return
	}

	// Increment plan version
	h.store.PG().ExecContext(ctx, "UPDATE journeys SET plan_version=plan_version+1, updated_at=now() WHERE journey_id=$1", req.JourneyID)
	h.store.PG().QueryRowContext(ctx, "SELECT plan_version FROM journeys WHERE journey_id=$1", req.JourneyID).Scan(&planVersion)

	middleware.WriteJSON(w, 201, map[string]interface{}{
		"data": map[string]interface{}{
			"journeyId":    req.JourneyID,
			"planVersion":  planVersion,
			"status":       "edited",
		},
	})
}

func (h *Handler) SplitJourney(w http.ResponseWriter, r *http.Request) {
	if !middleware.HasRole(r, "dispatcher") && !middleware.HasRole(r, "administrator") {
		middleware.WriteError(w, 403, "forbidden", "forbidden")
		return
	}

	var req struct {
		JourneyID           string   `json:"journeyId"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		SampleIDs           []string `json:"sampleIds"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "invalid_json", "invalid json")
		return
	}

	if len(req.SampleIDs) == 0 {
		middleware.WriteError(w, 400, "invalid_split", "must split at least one sample")
		return
	}

	ctx := r.Context()
	origPlan := h.loadJourneyPlan(ctx, req.JourneyID)
	if origPlan == nil {
		middleware.WriteError(w, 404, "not_found", "journey not found")
		return
	}

	// Create new journey for split samples
	newJourneyID := uuid.New().String()
	remainingIDs := []string{}
	for _, sid := range origPlan.SampleIDs {
		moved := false
		for _, splitID := range req.SampleIDs {
			if sid == splitID {
				moved = true
				break
			}
		}
		if !moved {
			remainingIDs = append(remainingIDs, sid)
		}
	}

	// Update original journey
	origSampleIDsJSON, _ := json.Marshal(remainingIDs)
	h.store.PG().ExecContext(ctx, "UPDATE journeys SET sample_ids=$1, plan_version=plan_version+1, updated_at=now() WHERE journey_id=$2", origSampleIDsJSON, req.JourneyID)

	// Create split journey
	splitSampleIDsJSON, _ := json.Marshal(req.SampleIDs)
	stopsJSON, _ := json.Marshal(origPlan.OrderedStops)
	h.store.PG().ExecContext(ctx,
		`INSERT INTO journeys (journey_id, parent_journey_id, plan_version, route_mode, status, estimated_delivery_at, sample_ids, ordered_stops, legs, valid)
		 VALUES ($1, $2, 1, $3, 'planned', $4, $5, $6, '[]', true)`,
		newJourneyID, req.JourneyID, origPlan.RouteMode, origPlan.EstimatedDeliveryAt, splitSampleIDsJSON, stopsJSON)

	for _, sid := range req.SampleIDs {
		h.store.PG().ExecContext(ctx, "UPDATE samples SET active_journey_id=$1 WHERE sample_id=$2", newJourneyID, sid)
	}

	splitPlan := h.loadJourneyPlan(ctx, newJourneyID)
	updatedOrigPlan := h.loadJourneyPlan(ctx, req.JourneyID)

	middleware.WriteJSON(w, 201, map[string]interface{}{
		"data": map[string]interface{}{
			"journey":      updatedOrigPlan,
			"splitJourney": splitPlan,
		},
	})
}

func (h *Handler) MergeJourneys(w http.ResponseWriter, r *http.Request) {
	if !middleware.HasRole(r, "dispatcher") && !middleware.HasRole(r, "administrator") {
		middleware.WriteError(w, 403, "forbidden", "forbidden")
		return
	}

	var req struct {
		JourneyIDs          []string `json:"journeyIds"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "invalid_json", "invalid json")
		return
	}

	ctx := r.Context()
	allSampleIDs := []string{}
	var estDelivery *time.Time
	routeMode := "batched"

	for _, jid := range req.JourneyIDs {
		plan := h.loadJourneyPlan(ctx, jid)
		if plan == nil {
			continue
		}
		allSampleIDs = append(allSampleIDs, plan.SampleIDs...)
		if plan.EstimatedDeliveryAt != nil {
			estDelivery = plan.EstimatedDeliveryAt
		}
	}

	if len(allSampleIDs) == 0 {
		middleware.WriteError(w, 400, "invalid_json", "no valid journeys to merge")
		return
	}

	newJourneyID := uuid.New().String()
	sampleIDsJSON, _ := json.Marshal(allSampleIDs)

	h.store.PG().ExecContext(ctx,
		`INSERT INTO journeys (journey_id, plan_version, route_mode, status, estimated_delivery_at, sample_ids, ordered_stops, legs, valid)
		 VALUES ($1, 1, $2, 'planned', $3, $4, '[]', '[]', true)`,
		newJourneyID, routeMode, estDelivery, sampleIDsJSON)

	// Cancel original journeys
	for _, jid := range req.JourneyIDs {
		h.store.PG().ExecContext(ctx, "UPDATE journeys SET status='cancelled', updated_at=now() WHERE journey_id=$1", jid)
	}

	for _, sid := range allSampleIDs {
		h.store.PG().ExecContext(ctx, "UPDATE samples SET active_journey_id=$1 WHERE sample_id=$2", newJourneyID, sid)
	}

	merged := h.loadJourneyPlan(ctx, newJourneyID)
	middleware.WriteJSON(w, 201, map[string]interface{}{"data": merged})
}

func (h *Handler) RerouteJourney(w http.ResponseWriter, r *http.Request) {
	if !middleware.HasRole(r, "dispatcher") && !middleware.HasRole(r, "administrator") {
		middleware.WriteError(w, 403, "forbidden", "forbidden")
		return
	}

	var req struct {
		JourneyID           string `json:"journeyId"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
		Reason              string `json:"reason"`
		IdempotencyKey      string `json:"idempotencyKey"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "invalid_json", "invalid json")
		return
	}

	ctx := r.Context()
	origPlan := h.loadJourneyPlan(ctx, req.JourneyID)
	if origPlan == nil {
		middleware.WriteError(w, 404, "not_found", "journey not found")
		return
	}
	if origPlan.PlanVersion != req.ExpectedPlanVersion {
		middleware.WriteError(w, 409, "stale_plan", "stale plan version")
		return
	}

	// Mark original as replaced
	h.store.PG().ExecContext(ctx, "UPDATE journeys SET replan_status='replaced', updated_at=now() WHERE journey_id=$1", req.JourneyID)

	// Create replacement journey
	newJourneyID := uuid.New().String()
	sampleIDsJSON, _ := json.Marshal(origPlan.SampleIDs)
	h.store.PG().ExecContext(ctx,
		`INSERT INTO journeys (journey_id, parent_journey_id, plan_version, route_mode, status, estimated_delivery_at, sample_ids, ordered_stops, legs, valid)
		 VALUES ($1, $2, 1, $3, 'planned', $4, $5, $6, $7, true)`,
		newJourneyID, req.JourneyID, origPlan.RouteMode, origPlan.EstimatedDeliveryAt, sampleIDsJSON, "[]", "[]")

	for _, sid := range origPlan.SampleIDs {
		h.store.PG().ExecContext(ctx, "UPDATE samples SET active_journey_id=$1 WHERE sample_id=$2", newJourneyID, sid)
	}

	replacement := h.loadJourneyPlan(ctx, newJourneyID)
	middleware.WriteJSON(w, 201, map[string]interface{}{
		"data": map[string]interface{}{
			"journeyId":          req.JourneyID,
			"replanStatus":       "replaced",
			"replacementPlanId":  newJourneyID,
			"replacementJourney": replacement,
		},
	})
}

func (h *Handler) ReportDisruption(w http.ResponseWriter, r *http.Request) {
	if !middleware.HasRole(r, "dispatcher") && !middleware.HasRole(r, "administrator") {
		middleware.WriteError(w, 403, "forbidden", "forbidden")
		return
	}

	var req struct {
		ResourceType   string `json:"resourceType"`
		ResourceID     string `json:"resourceId"`
		Reason         string `json:"reason"`
		OccurredAt     string `json:"occurredAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "invalid_json", "invalid json")
		return
	}

	validTypes := map[string]bool{"location": true, "node": true, "laboratory": true, "connection": true, "route": true, "worker": true, "capacity": true}
	if !validTypes[req.ResourceType] {
		middleware.WriteError(w, 400, "invalid_resource_type", "invalid resource type")
		return
	}

	ctx := r.Context()
	occurredAt, _ := time.Parse(time.RFC3339, req.OccurredAt)
	if occurredAt.IsZero() {
		occurredAt = time.Now()
	}

	// Deactivate resource
	switch req.ResourceType {
	case "location", "node", "laboratory":
		h.store.PG().ExecContext(ctx, "UPDATE locations SET active=false WHERE location_id=$1", req.ResourceID)
	case "connection", "route":
		h.store.PG().ExecContext(ctx, "UPDATE connections SET active=false WHERE connection_id=$1", req.ResourceID)
	case "worker":
		h.store.PG().ExecContext(ctx, "UPDATE users SET available=false WHERE user_id=$1", req.ResourceID)
	case "capacity":
		h.store.PG().ExecContext(ctx, "UPDATE location_capacity SET capacity_units=0, cooled_capacity_units=0 WHERE location_id=$1", req.ResourceID)
	}

	// Find affected samples
	affectedIDs := []string{}
	replacementIDs := []string{}

	rows, err := h.store.PG().QueryContext(ctx,
		`SELECT DISTINCT s.sample_id FROM samples s
		 JOIN journeys j ON s.active_journey_id=j.journey_id
		 WHERE j.status IN ('planned','in_progress') AND (j.valid=true)`)
	if err == nil {
		defer rows.Close()
		for rows.Next() {
			var sid string
			rows.Scan(&sid)
			affectedIDs = append(affectedIDs, sid)
		}
	}

	disruptionID := uuid.New().String()
	affectedJSON, _ := json.Marshal(affectedIDs)
	replacementJSON, _ := json.Marshal(replacementIDs)

	h.store.PG().ExecContext(ctx,
		`INSERT INTO disruptions (disruption_id, resource_type, resource_id, reason, occurred_at, affected_sample_ids, replacement_plan_ids, replan_status)
		 VALUES ($1,$2,$3,$4,$5,$6,$7,'replanned')`,
		disruptionID, req.ResourceType, req.ResourceID, req.Reason, occurredAt, affectedJSON, replacementJSON)

	h.logAudit(ctx, middleware.GetUserID(r), middleware.GetActiveRole(r), "report_disruption", req.ResourceType, req.ResourceID, true, map[string]interface{}{"reason": req.Reason})

	middleware.WriteJSON(w, 201, map[string]interface{}{
		"data": map[string]interface{}{
			"disruptionId":       disruptionID,
			"affectedSampleIds":  affectedIDs,
			"replacementPlanIds": replacementIDs,
			"replanStatus":       "replanned",
		},
	})
}

