func (h *Handler) CreateConnection(w http.ResponseWriter, r *http.Request) {
	if !middleware.HasRole(r, "administrator") {
		middleware.WriteError(w, 403, "forbidden", "forbidden")
		return
	}

	var req struct {
		FromLocationID string  `json:"fromLocationId"`
		ToLocationID   string  `json:"toLocationId"`
		TravelMinutes  int     `json:"travelMinutes"`
		CostUnits      float64 `json:"costUnits"`
		Cooled         bool    `json:"cooled"`
		Active         bool    `json:"active"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "invalid_json", "invalid json")
		return
	}
	if req.TravelMinutes < 1 {
		middleware.WriteError(w, 400, "invalid_connection", "invalid travel minutes")
		return
	}

	ctx := r.Context()
	var cid string
	err := h.store.PG().QueryRowContext(ctx,
		`INSERT INTO connections (from_location_id, to_location_id, travel_minutes, cost_units, cooled, active)
		 VALUES ($1,$2,$3,$4,$5,$6) RETURNING connection_id`,
		req.FromLocationID, req.ToLocationID, req.TravelMinutes, req.CostUnits, req.Cooled, req.Active).Scan(&cid)
	if err != nil {
		middleware.WriteError(w, 500, "internal_error", "create connection failed")
		return
	}

	h.store.PG().ExecContext(ctx,
		`INSERT INTO connection_capacity (connection_id, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units)
		 VALUES ($1, 100, 0, 50, 0) ON CONFLICT DO NOTHING`, cid)

	h.logAudit(ctx, middleware.GetUserID(r), middleware.GetActiveRole(r), "create_connection", "connection", cid, true, nil)

	middleware.WriteJSON(w, 201, map[string]interface{}{
		"data": map[string]interface{}{
			"connectionId":   cid,
			"fromLocationId": req.FromLocationID,
			"toLocationId":   req.ToLocationID,
			"travelMinutes":  req.TravelMinutes,
			"costUnits":      req.CostUnits,
			"cooled":         req.Cooled,
			"active":         req.Active,
		},
	})
}

