package handlers

import (
	"context"
	"crypto/rand"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"log"
	"math"
	"net/http"
	"strconv"
	"sync"
	"time"

	"lab-sample-system/middleware"
	"lab-sample-system/models"
	"lab-sample-system/store"

	"github.com/google/uuid"
	"github.com/gorilla/websocket"
	"go.mongodb.org/mongo-driver/bson"
	"go.mongodb.org/mongo-driver/mongo/options"
)

type Handler struct {
	store     *store.Store
	wsClients sync.Map // map[string]map[*wsConn]bool  (role -> connections)
	mu        sync.Mutex
}

type wsConn struct {
	conn    *websocket.Conn
	userID  string
	role    string
	roles   []string
	since   int64
}

var upgrader = websocket.Upgrader{CheckOrigin: func(r *http.Request) bool { return true }}

// resolveSampleTypeID resolves a sample type name or UUID to a UUID.
func (h *Handler) resolveSampleTypeID(ctx context.Context, nameOrID string) string {
// Try as UUID first
var id string
err := h.store.PG().QueryRowContext(ctx, "SELECT sample_type_id FROM sample_types WHERE sample_type_id=$1", nameOrID).Scan(&id)
if err == nil {
return id
}
// Try as name (case-insensitive)
err = h.store.PG().QueryRowContext(ctx, "SELECT sample_type_id FROM sample_types WHERE LOWER(name)=LOWER($1) ORDER BY created_at ASC LIMIT 1", nameOrID).Scan(&id)
if err == nil {
return id
}
return ""
}

func New(s *store.Store) *Handler {
	h := &Handler{store: s}
	go h.assignmentOfferExpirer()
	return h
}

// assignmentOfferExpirer periodically expires old offers
func (h *Handler) assignmentOfferExpirer() {
	ticker := time.NewTicker(15 * time.Second)
	for range ticker.C {
		ctx := context.Background()
		h.store.PG().ExecContext(ctx, `UPDATE assignments SET status='expired' WHERE status='offered' AND offer_expires_at < now()`)
	}
}

// ============================== SYSTEM ==============================

func (h *Handler) SystemReadiness(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		middleware.WriteError(w, 405, "method_not_allowed", "method not allowed")
		return
	}
	ctx, cancel := context.WithTimeout(r.Context(), 5*time.Second)
	defer cancel()

	if err := h.store.EnsurePG(ctx); err != nil {
		middleware.WriteJSON(w, 503, map[string]string{"status": "not_ready"})
		return
	}
	if err := h.store.EnsureMongo(ctx); err != nil {
		middleware.WriteJSON(w, 503, map[string]string{"status": "not_ready"})
		return
	}
	if err := h.store.EnsureRedis(ctx); err != nil {
		middleware.WriteJSON(w, 503, map[string]string{"status": "not_ready"})
		return
	}
	middleware.WriteJSON(w, 200, map[string]string{"status": "ready"})
}

// ============================== AUTH ==============================

func (h *Handler) AuthenticateUser(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Username        string `json:"username"`
		Password        string `json:"password"`
		InitialPassword string `json:"initialPassword"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "invalid_json", "invalid json")
		return
	}
	if req.Password == "" && req.InitialPassword != "" {
		req.Password = req.InitialPassword
	}

	ctx := r.Context()
	var uid, hash, fullName string
	var rolesJSON []byte
	err := h.store.PG().QueryRowContext(ctx, "SELECT user_id, password_hash, roles FROM users WHERE username=$1 AND active=true", req.Username).Scan(&uid, &hash, &rolesJSON)
	if err != nil {
		middleware.WriteError(w, 401, "invalid_credentials", "invalid credentials")
		return
	}

	var ok bool
	h.store.PG().QueryRowContext(ctx, "SELECT (password_hash = crypt($1, password_hash)) FROM users WHERE user_id=$2", req.Password, uid).Scan(&ok)
	if !ok {
		middleware.WriteError(w, 401, "invalid_credentials", "invalid credentials")
		return
	}

	var roles []string
	json.Unmarshal(rolesJSON, &roles)
	activeRole := ""
	if len(roles) > 0 {
		activeRole = roles[0]
	}

	// Persist active role
	h.store.PG().ExecContext(ctx, "UPDATE users SET active_role=$1 WHERE user_id=$2", activeRole, uid)

	token, err := middleware.GenerateToken(uid, activeRole, roles)
	if err != nil {
		middleware.WriteError(w, 500, "internal_error", "token generation failed")
		return
	}

	// Store session in redis
	sessionKey := "session:" + uid
	h.store.Redis().Set(ctx, sessionKey, token, 24*time.Hour)

	_ = fullName

	middleware.WriteJSON(w, 200, map[string]interface{}{
		"data": map[string]interface{}{
			"sessionToken": token,
			"userId":       uid,
			"roles":        roles,
			"activeRole":   activeRole,
		},
	})
}

func (h *Handler) SelectActiveRole(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Role string `json:"role"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "invalid_json", "invalid json")
		return
	}

	uid := middleware.GetUserID(r)
	ctx := r.Context()

	var rolesJSON []byte
	if err := h.store.PG().QueryRowContext(ctx, "SELECT roles FROM users WHERE user_id=$1", uid).Scan(&rolesJSON); err != nil {
		middleware.WriteError(w, 404, "not_found", "user not found")
		return
	}
	var roles []string
	json.Unmarshal(rolesJSON, &roles)

	hasRole := false
	for _, r := range roles {
		if r == req.Role {
			hasRole = true
			break
		}
	}
	if !hasRole {
		middleware.WriteError(w, 403, "role_not_held", "role not held")
		return
	}

	h.store.PG().ExecContext(ctx, "UPDATE users SET active_role=$1 WHERE user_id=$2", req.Role, uid)

	middleware.WriteJSON(w, 200, map[string]interface{}{
		"data": map[string]interface{}{
			"activeRole": req.Role,
			"roles":      roles,
		},
	})
}

// ============================== USERS ==============================

func (h *Handler) CreateUser(w http.ResponseWriter, r *http.Request) {
	if !middleware.HasRole(r, "administrator") {
		middleware.WriteError(w, 403, "forbidden", "forbidden")
		return
	}

	var req struct {
		Username           string                   `json:"username"`
		Password           string                   `json:"initialPassword"`
		FullName           string                   `json:"fullName"`
		Roles              []string                 `json:"roles"`
		Qualifications     []string                 `json:"qualifications"`
		Certifications     []models.Certification   `json:"certifications"`
		Active             bool                     `json:"active"`
		AssignedLocationID string                   `json:"assignedLocationId"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "invalid_json", "invalid json")
		return
	}
	if req.Username == "" || req.Password == "" {
		middleware.WriteError(w, 400, "invalid_json", "username and initialPassword required")
		return
	}

	ctx := r.Context()
	rolesJSON, _ := json.Marshal(req.Roles)
	qualsJSON, _ := json.Marshal(req.Qualifications)
	certsJSON, _ := json.Marshal(req.Certifications)

	var uid string
	locID := nullUUID(req.AssignedLocationID)
	err := h.store.PG().QueryRowContext(ctx,
		`INSERT INTO users (username, password_hash, full_name, roles, qualifications, certifications, active, assigned_location_id)
		 VALUES ($1, crypt($2, gen_salt('bf')), $3, $4, $5, $6, $7, $8) RETURNING user_id`,
		req.Username, req.Password, req.FullName, rolesJSON, qualsJSON, certsJSON, req.Active, locID).Scan(&uid)
	if err != nil {
		middleware.WriteError(w, 409, "concurrent_conflict", "username may already exist")
		return
	}

	h.logAudit(ctx, uid, middleware.GetActiveRole(r), "create_user", "user", uid, true, map[string]interface{}{"username": req.Username})

	activeRole := ""
	if len(req.Roles) > 0 {
		activeRole = req.Roles[0]
	}
	middleware.WriteJSON(w, 201, map[string]interface{}{
		"data": map[string]interface{}{
			"userId":             uid,
			"username":           req.Username,
			"fullName":           req.FullName,
			"roles":              req.Roles,
			"qualifications":     req.Qualifications,
			"certifications":     req.Certifications,
			"active":             req.Active,
			"assignedLocationId": req.AssignedLocationID,
			"activeRole":         activeRole,
		},
	})
}

func (h *Handler) ReadUser(w http.ResponseWriter, r *http.Request) {
	userID := r.PathValue("userId")
	if userID == "" {
		middleware.WriteError(w, 404, "not_found", "not found")
		return
	}

	ctx := r.Context()
	var u models.User
	var rolesJSON, qualsJSON, certsJSON []byte
	var assignedLoc *string
	err := h.store.PG().QueryRowContext(ctx,
		`SELECT user_id, username, full_name, roles, qualifications, certifications, active, assigned_location_id, active_role, available, capacity_units
		 FROM users WHERE user_id=$1`, userID).Scan(
		&u.UserID, &u.Username, &u.FullName, &rolesJSON, &qualsJSON, &certsJSON, &u.Active, &assignedLoc, &u.ActiveRole, &u.Available, &u.CapacityUnits)
	if err != nil {
		middleware.WriteError(w, 404, "not_found", "user not found")
		return
	}
	json.Unmarshal(rolesJSON, &u.Roles)
	json.Unmarshal(qualsJSON, &u.Qualifications)
	json.Unmarshal(certsJSON, &u.Certifications)
	if assignedLoc != nil {
		u.AssignedLocationID = *assignedLoc
	}

	middleware.WriteJSON(w, 200, map[string]interface{}{"data": u})
}

func (h *Handler) UpdateUserAccess(w http.ResponseWriter, r *http.Request) {
	if !middleware.HasRole(r, "administrator") {
		middleware.WriteError(w, 403, "forbidden", "forbidden")
		return
	}

	var req struct {
		UserID             string                 `json:"userId"`
		Roles              []string               `json:"roles"`
		Qualifications     []string               `json:"qualifications"`
		Certifications     []models.Certification `json:"certifications"`
		Active             bool                   `json:"active"`
		AssignedLocationID string                 `json:"assignedLocationId"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "invalid_json", "invalid json")
		return
	}

	ctx := r.Context()
	rolesJSON, _ := json.Marshal(req.Roles)
	qualsJSON, _ := json.Marshal(req.Qualifications)
	certsJSON, _ := json.Marshal(req.Certifications)
	locID := nullUUID(req.AssignedLocationID)

	_, err := h.store.PG().ExecContext(ctx,
		`UPDATE users SET roles=$1, qualifications=$2, certifications=$3, active=$4, assigned_location_id=$5, updated_at=now() WHERE user_id=$6`,
		rolesJSON, qualsJSON, certsJSON, req.Active, locID, req.UserID)
	if err != nil {
		middleware.WriteError(w, 404, "not_found", "user not found")
		return
	}

	h.logAudit(ctx, middleware.GetUserID(r), middleware.GetActiveRole(r), "update_user_access", "user", req.UserID, true, nil)

	middleware.WriteJSON(w, 201, map[string]interface{}{
		"data": map[string]interface{}{
			"userId":             req.UserID,
			"roles":              req.Roles,
			"qualifications":     req.Qualifications,
			"certifications":     req.Certifications,
			"active":             req.Active,
			"assignedLocationId": req.AssignedLocationID,
		},
	})
}

// ============================== LOCATIONS ==============================

func (h *Handler) CreateLocation(w http.ResponseWriter, r *http.Request) {
	if !middleware.HasRole(r, "administrator") {
		middleware.WriteError(w, 403, "forbidden", "forbidden")
		return
	}

	var req struct {
		Name            string                     `json:"name"`
		Coordinate      models.Coordinate          `json:"coordinate"`
		CoverageKm      float64                    `json:"coverageKm"`
		HandlingMinutes int                        `json:"handlingMinutes"`
		Active          bool                       `json:"active"`
		Functions       []string                   `json:"functions"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "invalid_json", "invalid json")
		return
	}
	if req.Coordinate.Latitude < -90 || req.Coordinate.Latitude > 90 {
		middleware.WriteError(w, 400, "invalid_coordinate", "invalid coordinate")
		return
	}
	if req.CoverageKm <= 0 || req.CoverageKm > 5 {
		middleware.WriteError(w, 400, "invalid_node_coverage", "invalid coverage")
		return
	}
	if req.HandlingMinutes < 0 || req.HandlingMinutes > 1440 {
		middleware.WriteError(w, 400, "invalid_handling_time", "invalid handling time")
		return
	}

	funcStates := models.LocationFunctionStates{}
	for _, f := range req.Functions {
		switch f {
		case "collection_point":
			funcStates.CollectionPoint = true
		case "transfer_point":
			funcStates.TransferPoint = true
		case "hub":
			funcStates.Hub = true
		case "laboratory":
			funcStates.Laboratory = true
		default:
			middleware.WriteError(w, 400, "invalid_location_function", "invalid location function")
			return
		}
	}

	funcJSON, _ := json.Marshal(funcStates)
	ctx := r.Context()

	var lid string
	err := h.store.PG().QueryRowContext(ctx,
		`INSERT INTO locations (name, latitude, longitude, coverage_km, handling_minutes, active, functions)
		 VALUES ($1,$2,$3,$4,$5,$6,$7) RETURNING location_id`,
		req.Name, req.Coordinate.Latitude, req.Coordinate.Longitude, req.CoverageKm, req.HandlingMinutes, req.Active, funcJSON).Scan(&lid)
	if err != nil {
		middleware.WriteError(w, 500, "internal_error", "create location failed")
		return
	}

	h.store.PG().ExecContext(ctx,
		`INSERT INTO location_capacity (location_id, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units)
		 VALUES ($1, 100, 0, 50, 0) ON CONFLICT DO NOTHING`, lid)

	h.logAudit(ctx, middleware.GetUserID(r), middleware.GetActiveRole(r), "create_location", "location", lid, true, nil)

	loc := models.Location{
		LocationID:      lid,
		Name:            req.Name,
		Coordinate:      req.Coordinate,
		CoverageKm:      req.CoverageKm,
		HandlingMinutes: req.HandlingMinutes,
		Active:          req.Active,
		Functions:       funcStates,
	}
	middleware.WriteJSON(w, 201, map[string]interface{}{"data": loc})
}

func (h *Handler) UpdateLocation(w http.ResponseWriter, r *http.Request) {
	if !middleware.HasRole(r, "administrator") {
		middleware.WriteError(w, 403, "forbidden", "forbidden")
		return
	}

	var req struct {
		LocationID      string          `json:"locationId"`
		Name            string          `json:"name"`
		Coordinate      models.Coordinate `json:"coordinate"`
		CoverageKm      float64         `json:"coverageKm"`
		HandlingMinutes int             `json:"handlingMinutes"`
		Functions       json.RawMessage `json:"functions"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "invalid_json", "invalid json")
		return
	}

	funcStates := models.LocationFunctionStates{}
	// Try as array of strings first
	var funcArr []string
	if err := json.Unmarshal(req.Functions, &funcArr); err == nil {
		for _, f := range funcArr {
			switch f {
			case "collection_point":
				funcStates.CollectionPoint = true
			case "transfer_point":
				funcStates.TransferPoint = true
			case "hub":
				funcStates.Hub = true
			case "laboratory":
				funcStates.Laboratory = true
			default:
				middleware.WriteError(w, 400, "invalid_location_function", "invalid location function")
				return
			}
		}
	} else if err := json.Unmarshal(req.Functions, &funcStates); err != nil {
		middleware.WriteError(w, 400, "invalid_json", "invalid functions format")
		return
	}

	funcJSON, _ := json.Marshal(funcStates)
	ctx := r.Context()

	_, err := h.store.PG().ExecContext(ctx,
		`UPDATE locations SET name=$1, latitude=$2, longitude=$3, coverage_km=$4, handling_minutes=$5, functions=$6, updated_at=now() WHERE location_id=$7`,
		req.Name, req.Coordinate.Latitude, req.Coordinate.Longitude, req.CoverageKm, req.HandlingMinutes, funcJSON, req.LocationID)
	if err != nil {
		middleware.WriteError(w, 404, "not_found", "location not found")
		return
	}

	loc := models.Location{
		LocationID:      req.LocationID,
		Name:            req.Name,
		Coordinate:      req.Coordinate,
		CoverageKm:      req.CoverageKm,
		HandlingMinutes: req.HandlingMinutes,
		Active:          true,
		Functions:       funcStates,
	}
	middleware.WriteJSON(w, 201, map[string]interface{}{"data": loc})
}

