		laboratory_id UUID NOT NULL REFERENCES locations(location_id),
		sample_type_id UUID NOT NULL REFERENCES sample_types(sample_type_id),
		accepts BOOLEAN NOT NULL DEFAULT false,
		UNIQUE(laboratory_id, sample_type_id)
	);

	CREATE TABLE IF NOT EXISTS location_capacity (
		location_id UUID PRIMARY KEY REFERENCES locations(location_id),
		capacity_units INT NOT NULL DEFAULT 0,
		reserved_units INT NOT NULL DEFAULT 0,
		cooled_capacity_units INT NOT NULL DEFAULT 0,
		cooled_reserved_units INT NOT NULL DEFAULT 0
	);

	CREATE TABLE IF NOT EXISTS connection_capacity (
