		replacement_plan_ids JSONB NOT NULL DEFAULT '[]',
		replan_status TEXT NOT NULL DEFAULT 'replanned',
		created_at TIMESTAMPTZ NOT NULL DEFAULT now()
	);

	-- Indexes
	CREATE INDEX IF NOT EXISTS idx_samples_requester ON samples(requester_id);
	CREATE INDEX IF NOT EXISTS idx_samples_holder ON samples(current_holder_id);
	CREATE INDEX IF NOT EXISTS idx_samples_journey ON samples(active_journey_id);
	CREATE INDEX IF NOT EXISTS idx_samples_status ON samples(status);
	CREATE INDEX IF NOT EXISTS idx_assignments_worker ON assignments(worker_id);
	CREATE INDEX IF NOT EXISTS idx_assignments_journey ON assignments(journey_id);
	CREATE INDEX IF NOT EXISTS idx_assignments_status ON assignments(status);
	CREATE INDEX IF NOT EXISTS idx_journeys_status ON journeys(status);
	CREATE INDEX IF NOT EXISTS idx_handoffs_sample ON handoffs(sample_id);
	CREATE INDEX IF NOT EXISTS idx_capacity_resource ON capacity_reservations(resource_type, resource_id);
	`

	_, err := s.pg.ExecContext(ctx, ddl)
	if err != nil {
		return fmt.Errorf("migrations: %w", err)
	}

	// Ensure MongoDB collections and indexes
	auditColl := s.mongo.Collection("audit_logs")
	auditColl.Indexes().CreateMany(ctx, []mongo.IndexModel{
		{Keys: bson.D{{Key: "entity_id", Value: 1}}},
		{Keys: bson.D{{Key: "actor_id", Value: 1}}},
		{Keys: bson.D{{Key: "occurred_at", Value: -1}}},
		{Keys: bson.D{{Key: "entity_type", Value: 1}}},
		{Keys: bson.D{{Key: "action", Value: 1}}},
	})

	eventsColl := s.mongo.Collection("events")
	eventsColl.Indexes().CreateMany(ctx, []mongo.IndexModel{
		{Keys: bson.D{{Key: "id", Value: 1}}},
	})

	timelineColl := s.mongo.Collection("timeline_events")
	timelineColl.Indexes().CreateMany(ctx, []mongo.IndexModel{
		{Keys: bson.D{{Key: "sample_id", Value: 1}}},
		{Keys: bson.D{{Key: "event_id", Value: 1}}},
	})

	return nil
}

// Reset clears all application data
func (s *Store) Reset(ctx context.Context) error {
	tables := []string{
		"disruptions", "handling_checkpoints", "capacity_reservations",
		"handoffs", "assignments", "journeys", "samples",
		"laboratory_acceptances", "connection_capacity", "location_capacity",
		"serviceability_versions", "sample_types", "connections", "locations", "users",
	}
	for _, t := range tables {
		if _, err := s.pg.ExecContext(ctx, "DELETE FROM "+t); err != nil {
			return fmt.Errorf("reset %s: %w", t, err)
		}
	}

	// Reset MongoDB collections
	if _, err := s.mongo.Collection("audit_logs").DeleteMany(ctx, bson.M{}); err != nil {
		return fmt.Errorf("reset audit_logs: %w", err)
	}
	if _, err := s.mongo.Collection("events").DeleteMany(ctx, bson.M{}); err != nil {
		return fmt.Errorf("reset events: %w", err)
	}
	if _, err := s.mongo.Collection("timeline_events").DeleteMany(ctx, bson.M{}); err != nil {
		return fmt.Errorf("reset timeline_events: %w", err)
	}

	// Clear Redis keys
	s.redis.FlushAll(ctx)
	s.eventSeq = 0
	s.redis.Set(ctx, "event:seq", 0, 0)

	return nil
}

func (s *Store) CreateAdmin(ctx context.Context) error {
	username := os.Getenv("ADMIN_USERNAME")
	password := os.Getenv("ADMIN_PASSWORD")
	if username == "" || password == "" {
		return nil
	}

	var count int
	if err := s.pg.QueryRowContext(ctx, "SELECT COUNT(*) FROM users WHERE username = $1", username).Scan(&count); err != nil {
		return err
	}
	if count > 0 {
		return nil
	}

	roles, _ := json.Marshal([]string{"administrator"})
	_, err := s.pg.ExecContext(ctx,
		"INSERT INTO users (username, password_hash, full_name, roles, active, active_role) VALUES ($1, crypt($2, gen_salt('bf')), $3, $4, true, 'administrator')",
		username, password, "Administrator", roles)
	if err != nil {
		return fmt.Errorf("create admin: %w", err)
	}

	log.Printf("Created admin user: %s", username)
	return nil
}

