func (h *Handler) ConfigureLaboratoryAcceptance(w http.ResponseWriter, r *http.Request) {
	if !middleware.HasRole(r, "administrator") {
		middleware.WriteError(w, 403, "forbidden", "forbidden")
		return
	}

	var req struct {
		LaboratoryID string `json:"laboratoryId"`
		SampleTypeID string `json:"sampleTypeId"`
		Accepts      bool   `json:"accepts"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "invalid_json", "invalid json")
		return
	}

	ctx := r.Context()
	stID := h.resolveSampleTypeID(ctx, req.SampleTypeID)
	if stID == "" {
		middleware.WriteError(w, 404, "not_found", "sample type not found")
		return
	}

	var aid string
	err := h.store.PG().QueryRowContext(ctx,
		`INSERT INTO laboratory_acceptances (laboratory_id, sample_type_id, accepts)
		 VALUES ($1,$2,$3) ON CONFLICT (laboratory_id, sample_type_id) DO UPDATE SET accepts=$3 RETURNING acceptance_id`,
		req.LaboratoryID, stID, req.Accepts).Scan(&aid)
	if err != nil {
		middleware.WriteError(w, 500, "internal_error", fmt.Sprintf("configure lab acceptance: %v", err))
		return
	}

	middleware.WriteJSON(w, 200, map[string]interface{}{
		"data": map[string]interface{}{
			"acceptanceId": aid,
			"accepts":      req.Accepts,
		},
	})
}

