[?2004lfunc (h *Handler) createJourney(ctx context.Context, journeyID, sampleID string, origin models.Coordinate, targetLabID, sampleTypeID, containerType string, earliestAt, latestAt *time.Time, deadline time.Time) {
	// Find a collection node near origin
	var collectionNodeID string
	var nodeLat, nodeLng float64
	h.store.PG().QueryRowContext(ctx,
		`SELECT location_id, latitude, longitude FROM locations WHERE functions->>'collection_point' = 'true' ORDER BY (latitude-$1)^2+(longitude-$2)^2 LIMIT 1`,
		origin.Latitude, origin.Longitude).Scan(&collectionNodeID, &nodeLat, &nodeLng)

	pickupID := uuid.New().String()
	now := time.Now()

	// Create stops
	if earliestAt == nil {
		earliestAt = &now
	}
	if latestAt == nil {
		t := now.Add(4 * time.Hour)
		latestAt = &t
	}

	stops := []models.JourneyStop{
		{StopID: pickupID, LocationID: collectionNodeID, StopType: "pickup", Sequence: 1, EstimatedAt: *earliestAt, DwellMinutes: 15, Coordinate: &origin},
	}
	if collectionNodeID != targetLabID {
		stops = append(stops, models.JourneyStop{
			StopID: uuid.New().String(), LocationID: targetLabID, StopType: "delivery", Sequence: 2, EstimatedAt: deadline, DwellMinutes: 10,
		})
	}

	stopsJSON, _ := json.Marshal(stops)

	// Create transport assignment
	transAssignID := uuid.New().String()
	h.store.PG().ExecContext(ctx,
		`INSERT INTO assignments (assignment_id, kind, sample_id, journey_id, from_location_id, to_location_id, sequence, status, offer_expires_at)
		 VALUES ($1,'transport',$2,$3,$4,$5,2,'offered', $6)`,
		transAssignID, sampleID, journeyID, collectionNodeID, targetLabID, now.Add(5*time.Minute))

	legs := []models.JourneyLeg{
		{AssignmentID: transAssignID, Sequence: 1, Status: "offered", FromLocationID: collectionNodeID, ToLocationID: targetLabID, SampleID: sampleID},
	}
	legsJSON, _ := json.Marshal(legs)
	sampleIDsJSON, _ := json.Marshal([]string{sampleID})

	h.store.PG().ExecContext(ctx,
		`INSERT INTO journeys (journey_id, plan_version, route_mode, status, estimated_delivery_at, sample_ids, ordered_stops, legs, first_transport_assignment_id, valid)
		 VALUES ($1, 1, 'direct', 'planned', $2, $3, $4, $5, $6, true)`,
		journeyID, deadline, sampleIDsJSON, stopsJSON, legsJSON, transAssignID)
