	h.store.PG().QueryRowContext(ctx, "SELECT status FROM assignments WHERE assignment_id=$1 AND worker_id=$2", req.AssignmentID, uid).Scan(&assignmentStatus)
	if assignmentStatus != "accepted" && assignmentStatus != "in_progress" {
		middleware.WriteError(w, 409, "assignment_inactive", "assignment not active")
		return
	}

	// Get sample type for handling check
	var sampleTypeID string
	var stContainer string
	var tempMin, tempMax float64
	h.store.PG().QueryRowContext(ctx,
		`SELECT s.sample_type_id, st.container_type, st.temperature_min_c, st.temperature_max_c
		 FROM samples s JOIN sample_types st ON s.sample_type_id=st.sample_type_id
		 WHERE s.sample_id=$1`, req.SampleID).Scan(&sampleTypeID, &stContainer, &tempMin, &tempMax)

	handlingCompliant := true
	if req.ObservedTemperatureC < tempMin || req.ObservedTemperatureC > tempMax {
		handlingCompliant = false
	}
	if req.ContainerType != stContainer {
		handlingCompliant = false
	}

	if !handlingCompliant {
		middleware.WriteError(w, 400, "handling_noncompliant", "handling noncompliant")
		return
	}

	// Update sample
	h.store.PG().ExecContext(ctx,
		`UPDATE samples SET status='sealed', sealed=true, current_holder_id=$1, container_type=$2, updated_at=now() WHERE sample_id=$3`,
		uid, req.ContainerType, req.SampleID)

	// Update assignment
	h.store.PG().ExecContext(ctx, "UPDATE assignments SET status='completed' WHERE assignment_id=$1", req.AssignmentID)

	h.addTimeline(ctx, req.SampleID, "collected_and_sealed", uid, middleware.GetActiveRole(r), true, nil)
	h.logAudit(ctx, uid, middleware.GetActiveRole(r), "collect_and_seal", "sample", req.SampleID, true, nil)

	middleware.WriteJSON(w, 201, map[string]interface{}{
		"data": map[string]interface{}{
			"sampleId":          req.SampleID,
			"status":            "sealed",
			"currentHolderId":   uid,
			"sealedAt":          collectedAt,
			"handlingCompliant": handlingCompliant,
		},
	})
}

