func (h *Handler) IngestPresealedSample(w http.ResponseWriter, r *http.Request) {
	role := middleware.GetActiveRole(r)
	if role != "collection_professional" && role != "node_handler" && role != "laboratory_team" && role != "relay_courier" && role != "administrator" {
		middleware.WriteError(w, 403, "forbidden", "forbidden")
