// Check certification / qualification
		var certJSON []byte
		var qualJSON []byte
		h.store.PG().QueryRowContext(ctx, "SELECT certifications, qualifications FROM users WHERE user_id=$1", uid).Scan(&certJSON, &qualJSON)
		var certs []models.Certification
		var quals []string
		json.Unmarshal(certJSON, &certs)
		json.Unmarshal(qualJSON, &quals)
		hasCert := false
		for _, c := range certs {
			if c.Active {
				hasCert = true
				break
			}
		}
		// Also check qualifications as fallback
		if !hasCert && len(quals) > 0 {
			// Get the sample's required qualification
			var requiredQual string
			h.store.PG().QueryRowContext(ctx,
				`SELECT st.required_qualification FROM sample_types st
				 JOIN samples s ON s.sample_type_id = st.sample_type_id
				 WHERE s.sample_id=$1`, req.SampleID).Scan(&requiredQual)
			for _, q := range quals {
				if q == requiredQual || requiredQual == "" {
					hasCert = true
					break
				}
			}
		}
		if !hasCert {
			middleware.WriteError(w, 409, "certification_inactive", "no active certification")
			return
		}

